INSERT OR REPLACE INTO exams (id, code, title, language_code, level, duration_minutes, pass_score, total_score, require_camera, require_mic, shuffle_questions, shuffle_options, starts_at, ends_at, status, created_at) VALUES ('exam_wb_en_b1', 'WB-EXAM-EN-2026', 'Kỳ thi Đánh giá Năng lực Thực hành Tiếng Anh Chuẩn B1 – HỆ THỐNG KHẢO THÍ WORD BRIDGE', 'en', 'B1', 45, 60, 100, 0, 0, 1, 1, '2026-01-01T00:00:00.000Z', '2027-12-31T23:59:59.000Z', 'published', '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO exams (id, code, title, language_code, level, duration_minutes, pass_score, total_score, require_camera, require_mic, shuffle_questions, shuffle_options, starts_at, ends_at, status, created_at) VALUES ('exam_wb_zh_hsk2', 'WB-EXAM-ZH-2026', 'Kỳ thi Đánh giá Năng lực Tiếng Trung HSK 2 – HỆ THỐNG KHẢO THÍ WORD BRIDGE', 'zh', 'HSK 2', 40, 60, 100, 1, 0, 1, 1, '2026-01-01T00:00:00.000Z', '2027-12-31T23:59:59.000Z', 'published', '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO exam_questions (id, exam_id, language_code, question_type, topic, level, prompt, options_json, correct_answer_json, explanation, points, version, created_by, created_at) VALUES ('eq_en_1', 'exam_wb_en_b1', 'en', 'single_choice', 'Grammar & Context', 'B1', 'Choose the best word to complete the sentence: ''Effective language acquisition requires regular ___ with peers.''', '["interaction", "isolation", "hesitation", "limitation"]', '{"answer": "interaction"}', '''interaction'' (sự tương tác) phù hợp nhất với ngữ cảnh thực hành ngoại ngữ cùng bạn học.', 20, 1, 'system', '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO exam_questions (id, exam_id, language_code, question_type, topic, level, prompt, options_json, correct_answer_json, explanation, points, version, created_by, created_at) VALUES ('eq_en_2', 'exam_wb_en_b1', 'en', 'multiple_choice', 'Reading & Vocabulary', 'B1', 'Select ALL actions that directly improve active language retention:', '["Practicing listening fill-in-the-blank daily", "Reviewing vocabulary flashcards in context", "Sharing and discussing texts in a study group", "Never speaking or writing the language"]', '{"answers": ["Practicing listening fill-in-the-blank daily", "Reviewing vocabulary flashcards in context", "Sharing and discussing texts in a study group"]}', 'Ba hoạt động đầu đều tạo phản xạ chủ động theo mô hình LEARN - CONNECT - COMMUNITY - GROW.', 20, 1, 'system', '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO exam_questions (id, exam_id, language_code, question_type, topic, level, prompt, options_json, correct_answer_json, explanation, points, version, created_by, created_at) VALUES ('eq_en_3', 'exam_wb_en_b1', 'en', 'true_false', 'Comprehension', 'B1', 'Statement: ''Learning words inside complete example sentences helps learners understand appropriate usage better than memorizing isolated words.''', '["Đúng", "Sai"]', '{"answer": "Đúng"}', 'Học từ vựng đặt trong câu ví dụ giúp nắm bắt ngữ cảnh sử dụng chính xác hơn.', 20, 1, 'system', '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO exam_questions (id, exam_id, language_code, question_type, topic, level, prompt, options_json, correct_answer_json, explanation, points, version, created_by, created_at) VALUES ('eq_en_4', 'exam_wb_en_b1', 'en', 'fill_blank', 'Sentence Structure', 'B1', 'Fill in the missing preposition: ''She has been participating ___ the English speaking club since October.''', '[]', '{"answer": "in"}', 'Động từ ''participate'' đi kèm giới từ ''in'' (participate in = tham gia vào).', 20, 1, 'system', '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO exam_questions (id, exam_id, language_code, question_type, topic, level, prompt, options_json, correct_answer_json, explanation, points, version, created_by, created_at) VALUES ('eq_en_5', 'exam_wb_en_b1', 'en', 'ordering', 'Sentence Building', 'B1', 'Arrange the segments to form a complete conditional sentence:', '["If you practice every day,", "your confidence in speaking", "will grow steadily."]', '{"answer": ["If you practice every day,", "your confidence in speaking", "will grow steadily."]}', 'Câu điều kiện loại 1 diễn tả kết quả thực tế xảy ra khi duy trì thói quen luyện tập.', 20, 1, 'system', '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO cms_pages (id, slug, title, page_group, html_content, blocks_json, seo_title, seo_description, status, version, updated_by, updated_at) VALUES ('cms_home', '/', 'Trang chủ WORD BRIDGE', 'public', '<section class=''wb-cms-block''><h2>WORD BRIDGE – Where Languages Bring People Together.</h2><p>Nền tảng thực hành ngoại ngữ, kết nối bạn học và vận hành câu lạc bộ/tổ chức trên một địa chỉ duy nhất https://wordbridge.io.vn.</p></section>', '[]', 'WORD BRIDGE – Where Languages Bring People Together.', 'Nền tảng thực hành 5 ngôn ngữ, kết nối bạn học và cộng đồng ngoại ngữ.', 'published', 1, 'system', '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO cms_pages (id, slug, title, page_group, html_content, blocks_json, seo_title, seo_description, status, version, updated_by, updated_at) VALUES ('cms_about', '/gioi-thieu', 'Giới thiệu WORD BRIDGE', 'public', '<section class=''wb-cms-block''><h2>Về Đề án Khởi nghiệp WORD BRIDGE (2026–2027)</h2><p>WORD BRIDGE hợp nhất công cụ tự rèn luyện 05 ngôn ngữ (Tiếng Trung, Tiếng Anh, Tiếng Hàn, Tiếng Nhật, Tiếng Nga), bộ lọc tìm bạn đồng hành và không gian vận hành câu lạc bộ/tổ chức vào chung một nền tảng duy nhất.</p></section>', '[]', 'Giới thiệu WORD BRIDGE', 'Đề án Nền tảng Thực hành và Kết nối Cộng đồng Ngoại ngữ WORD BRIDGE.', 'published', 1, 'system', '2026-11-15T00:00:00.000Z');
INSERT OR REPLACE INTO cms_pages (id, slug, title, page_group, html_content, blocks_json, seo_title, seo_description, status, version, updated_by, updated_at) VALUES ('cms_legal', '/phap-ly', 'Chính sách, Điều khoản và Bảo vệ Dữ liệu Cá nhân', 'policy', '<section class=''wb-cms-block''><h2>Hệ thống Quy chế Pháp lý & Bảo vệ Người chưa thành niên</h2><p>Bao gồm: Điều khoản sử dụng, Chính sách quyền riêng tư, Chính sách dữ liệu cá nhân, Quy chế cộng đồng, Chính sách bản quyền, Chính sách thanh toán & hoàn tiền, Chính sách bảo vệ trẻ em và Quy trình xử lý khiếu nại.</p></section>', '[]', 'Chính sách & Pháp lý WORD BRIDGE', 'Điều khoản dịch vụ, bảo vệ dữ liệu cá nhân và an toàn cộng đồng.', 'published', 1, 'system', '2026-11-15T00:00:00.000Z');
