INSERT OR REPLACE INTO admin_source_vault_files (id, file_name, file_path, category, version_tag, mime_type, size_bytes, checksum_sha256, content_text, content_base64, description, uploaded_by, created_at, updated_at) VALUES ('svf_wrangler_config', 'wrangler.toml', '/wrangler.toml', 'infrastructure', 'v2026.3-ZeroR2', 'text/plain', 1213, '6cf3a34f2065a83ff9f0df7e36864958fbb3acbb53d5cda91f84c841b245343b', 'name = "wordbridge-edu"
main = "src/worker.js"
compatibility_date = "2026-11-01"
compatibility_flags = ["nodejs_compat"]

[assets]
directory = "./src/frontend"
binding = "ASSETS"
not_found_handling = "single-page-application"

[vars]
APP_NAME = "WORD BRIDGE"
APP_SLOGAN = "Where Languages Bring People Together."
CANONICAL_ORIGIN = "https://wordbridge.io.vn"
DEFAULT_LOCALE = "vi-VN"
TIMEZONE = "Asia/Ho_Chi_Minh"
MONTHLY_QUOTA_GB = "50"
STORAGE_ENGINE_MODE = "WEB_INTERNAL_VAULT_ZERO_R2"
EMAIL_FROM_NOREPLY = "noreply@wordbridge.io.vn"
EMAIL_FROM_NAME = "WORD BRIDGE – Email tự động từ hệ thống"
EMAIL_OFFICIAL_CONTACT = "wordbridge.education@gmail.com"
EMAIL_CSKH = "cskh@wordbridge.io.vn"
EMAIL_PARTNERSHIP = "contact@wordbridge.io.vn"

[[d1_databases]]
binding = "DB"
database_name = "word"
database_id = "ce84cc48-6d49-409b-b45a-13ba3bc4a771"
migrations_dir = "database/migrations"

