INSERT OR REPLACE INTO admin_source_vault_files (id, file_name, file_path, category, version_tag, mime_type, size_bytes, checksum_sha256, content_text, content_base64, description, uploaded_by, created_at, updated_at) VALUES ('svf_github_deploy_workflow', 'deploy-cloudflare-workers.yml', '/.github/workflows/deploy-cloudflare-workers.yml', 'ci_cd', 'v2026.3-ZeroR2', 'text/plain', 792, '14b18e044a10c6412e0a8d1f0257fcd547ca438bc008ba3466b239777f4a7a22', 'name: Deploy WORD BRIDGE to Cloudflare Workers (Zero-R2)
on:
  push:
    branches: [ main, master ]
  workflow_dispatch:

jobs:
  deploy:
    runs-on: ubuntu-latest
    name: Build, Verify & Deploy Worker
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
      - name: Setup Node.js 22
        uses: actions/setup-node@v4
        with:
          node-version: ''22''
      - name: Verify Zero-R2 Architecture & Run System Tests
        run: |
          node scripts/manage.js verify
          node tests/full-system.test.js
      - name: Deploy to Cloudflare Workers
        uses: cloudflare/wrangler-action@v3
        with:
          apiToken: ${{ secrets.CLOUDFLARE_API_TOKEN }}
          accountId: ${{ secrets.CLOUDFLARE_ACCOUNT_ID }}
          command: deploy
', '', 'Workflow tự động Deploy từ GitHub lên Cloudflare Workers không dùng R2', 'Bùi Tấn Lộc (Trưởng nhóm)', '2026-11-17T00:00:00.000Z', '2026-11-17T00:00:00.000Z');
INSERT OR REPLACE INTO career_scenarios (id, slug, title, major, target_audience, level, summary, duration_minutes, is_free, vocab_json, phrases_json, dialogue_json, role_a_json, role_b_json, rubric_json, author_name, reviewed_by_teacher, source_attribution, display_order, created_at) VALUES ('csc_1', 'bao-cao-su-co-thiet-bi-co-khi', 'Báo cáo sự cố thiết bị cho khách hàng nước ngoài', 'Cơ khí', 'Học sinh, sinh viên Cao đẳng nghề • Trung cấp nghề • GDNN - GDTX', 'Cơ bản (A2)', 'Tình huống chuẩn ngành Cơ khí: kỹ thuật viên thông báo tình trạng dừng máy, mô tả nguyên nhân hư hỏng vòng bi trục chính và đề xuất phương án khắc phục cho đại diện khách hàng.', 15, 1, '[{"word":"malfunction","phonetic":"/ˌmælˈfʌŋk.ʃən/","pos":"noun / verb","meaning":"sự cố, trục trặc hoạt động của máy","example":"We detected a minor malfunction in the cooling unit."},{"word":"spindle bearing","phonetic":"/ˈspɪn.dəl ˈbeə.rɪŋ/","pos":"noun","meaning":"vòng bi trục chính","example":"The spindle bearing needs replacement due to overheating."},{"word":"downtime","phonetic":"/ˈdaʊn.taɪm/","pos":"noun","meaning":"thời gian máy ngừng hoạt động","example":"We aim to keep machine downtime under two hours."},{"word":"overheat","phonetic":"/ˌoʊ.vərˈhiːt/","pos":"verb","meaning":"quá nhiệt","example":"The motor started to overheat after continuous operation."},{"word":"spare part","phonetic":"/sper pɑːrt/","pos":"noun","meaning":"phụ tùng thay thế","example":"Do we have the spare part in the warehouse?"}]', '[{"en":"I am calling to report an unexpected issue on Line 2.","vi":"Tôi gọi để báo cáo một sự cố phát sinh ở Dây chuyền số 2.","context":"Mở đầu cuộc gọi báo cáo sự cố rõ ràng, đi thẳng vào vấn đề."},{"en":"Our initial inspection shows that the bearing overheated.","vi":"Kiểm tra ban đầu của chúng tôi cho thấy vòng bi đã bị quá nhiệt.","context":"Trình bày nguyên nhân kỹ thuật dựa trên kiểm tra sơ bộ."},{"en":"The estimated repair time is about ninety minutes.","vi":"Thời gian sửa chữa dự kiến khoảng 90 phút.","context":"Báo thời gian gián đoạn (downtime) để khách hàng chủ động kế hoạch."},{"en":"To prevent this from happening again, we will check lubrication every shift.","vi":"Để tránh lặp lại sự cố này, chúng tôi sẽ kiểm tra bôi trơn sau mỗi ca.","context":"Đề xuất biện pháp phòng ngừa sau khắc phục."}]', '[{"role":"A","speakerName":"Kỹ thuật viên (An)","en":"Good morning, Mr. Tanaka. I am calling to report a sudden stop on CNC machine number three.","vi":"Chào anh Tanaka. Tôi gọi để báo cáo việc máy CNC số 3 vừa dừng đột ngột."},{"role":"B","speakerName":"Đại diện khách hàng (Tanaka)","en":"Thanks for letting me know quickly. What seems to be the cause of the malfunction?","vi":"Cảm ơn bạn đã báo sớm. Nguyên nhân trục trặc có vẻ là gì vậy?"},{"role":"A","speakerName":"Kỹ thuật viên (An)","en":"Our initial inspection shows the spindle bearing overheated and triggered the safety sensor.","vi":"Kiểm tra ban đầu cho thấy vòng bi trục chính bị quá nhiệt và kích hoạt cảm biến an toàn."},{"role":"B","speakerName":"Đại diện khách hàng (Tanaka)","en":"Do you have the spare part on site, and how long will the downtime be?","vi":"Bên bạn có sẵn phụ tùng tại xưởng không, và thời gian dừng máy sẽ kéo dài bao lâu?"},{"role":"A","speakerName":"Kỹ thuật viên (An)","en":"Yes, we have two spare bearings in stock. The estimated repair time is about ninety minutes.","vi":"Có ạ, kho còn hai vòng bi dự phòng. Thời gian sửa chữa dự kiến khoảng 90 phút."},{"role":"B","speakerName":"Đại diện khách hàng (Tanaka)","en":"Please proceed with the replacement and send me a short test report once the machine runs again.","vi":"Hãy tiến hành thay thế và gửi tôi báo cáo chạy thử ngắn sau khi máy hoạt động lại nhé."}]', '{"title":"Vai A · Kỹ thuật viên Cơ khí","goal":"Thông báo kịp thời sự cố dừng máy, nêu rõ nguyên nhân và cam kết thời gian khắc phục.","tasks":["Nêu mã máy gặp sự cố và hiện tượng bất thường (quá nhiệt / rung lắc).","Giải thích ngắn gọn nguyên nhân kiểm tra ban đầu bằng thuật ngữ đúng.","Xác nhận tình trạng phụ tùng thay thế và ước tính downtime cụ thể."]}', '{"title":"Vai B · Giám sát / Khách hàng nước ngoài","goal":"Nắm bắt mức độ ảnh hưởng tiến độ sản xuất và yêu cầu xác nhận an toàn sau sửa chữa.","tasks":["Hỏi nguyên nhân cụ thể và kiểm tra xem có ảnh hưởng chất lượng lô hàng đang chạy không.","Xác nhận thời gian máy chạy lại và tiến độ giao hàng.","Yêu cầu gửi báo cáo kiểm tra vận hành (test report) sau khi hoàn tất."]}', '[{"id":"terminology","criterion":"Thuật ngữ chuyên ngành","description":"Dùng đúng và tự nhiên các từ vựng, cụm từ kỹ thuật/nghề nghiệp của tình huống.","maxScore":5},{"id":"clarity","criterion":"Phát âm & Độ rõ ý","description":"Phát âm từ khóa quan trọng (thông số, lỗi, hành động) dễ hiểu với bạn cùng luyện.","maxScore":5},{"id":"task_completion","criterion":"Xử lý đúng trọng tâm","description":"Hoàn thành đầy đủ nhiệm vụ của vai đóng và phản hồi sát câu hỏi đối phương.","maxScore":5},{"id":"interaction","criterion":"Phản xạ & Xác nhận thông tin","description":"Biết hỏi lại khi chưa rõ, xác nhận thông số/thời hạn để tránh hiểu nhầm công việc.","maxScore":5},{"id":"professionalism","criterion":"Thái độ nghề nghiệp","description":"Giữ giọng điệu lịch sự, hợp tác và đúng quy tắc an toàn/văn hóa nơi làm việc.","maxScore":5}]', 'Cao Anh Nhựt', 'GV chuyên môn Khoa Cơ khí · Trường CĐ nghề Việt Nam - Singapore', 'Biên soạn từ tình huống thực tập xưởng Cơ khí VSVC; sử dụng AI hỗ trợ kiểm tra chính tả tiếng Anh.', 1, '2026-11-17T00:00:00.000Z');
INSERT OR REPLACE INTO career_scenarios (id, slug, title, major, target_audience, level, summary, duration_minutes, is_free, vocab_json, phrases_json, dialogue_json, role_a_json, role_b_json, rubric_json, author_name, reviewed_by_teacher, source_attribution, display_order, created_at) VALUES ('csc_2', 'doc-ban-ve-ky-thuat-va-dung-sai-cnc', 'Trao đổi thông số bản vẽ kỹ thuật & dung sai gia công CNC', 'Cơ khí', 'Học sinh, sinh viên Cao đẳng nghề • Trung cấp nghề • GDNN - GDTX', 'Trung bình (B1)', 'Thực hành đọc và xác nhận kích thước, dung sai (±0.02 mm), độ nhám bề mặt và vật liệu phôi giữa thợ gia công CNC và kỹ sư thiết kế.', 15, 1, '[{"word":"tolerance","phonetic":"/ˈtɑːl.ər.əns/","pos":"noun","meaning":"dung sai cho phép","example":"The hole diameter requires a tight tolerance of plus or minus 0.02 millimeters."},{"word":"blueprint","phonetic":"/ˈbluː.prɪnt/","pos":"noun","meaning":"bản vẽ kỹ thuật","example":"Please double-check revision B on the blueprint before milling."},{"word":"surface roughness","phonetic":"/ˈsɜːr.fɪs ˈrʌf.nəs/","pos":"noun","meaning":"độ nhám bề mặt","example":"What is the required surface roughness for the contact face?"},{"word":"caliper","phonetic":"/ˈkæl.ɪ.pər/","pos":"noun","meaning":"thước cặp đo kiểm","example":"Use a digital caliper to verify the outer shaft width."},{"word":"chamfer","phonetic":"/ˈtʃæm.fər/","pos":"noun / verb","meaning":"vát mép cạnh","example":"Add a 1-millimeter chamfer along all sharp edges."}]', '[{"en":"Could you confirm whether we are following Revision B of the drawing?","vi":"Bạn có thể xác nhận xem chúng ta đang làm theo Bản vẽ sửa đổi B không?","context":"Kiểm tra đúng phiên bản bản vẽ trước khi gá phôi gia công."},{"en":"The inner bore has a tolerance of plus or minus 0.02 mm.","vi":"Đường kính lỗ trong có dung sai cộng trừ 0.02 mm.","context":"Đọc thông số dung sai chuẩn xác."},{"en":"We noticed a sharp edge here—should we add a 1 mm chamfer?","vi":"Chúng tôi thấy có cạnh sắc ở đây—có cần vát mép 1 mm không?","context":"Hỏi làm rõ chi tiết gia công còn thiếu trên bản vẽ."}]', '[{"role":"A","speakerName":"Thợ CNC (Hùng)","en":"Hi David, before I start the batch, could you confirm we are using Revision B of the shaft blueprint?","vi":"Chào David, trước khi chạy loạt sản phẩm, anh xác nhận giúp mình đang dùng Bản sửa đổi B của bản vẽ trục nhé?"},{"role":"B","speakerName":"Kỹ sư thiết kế (David)","en":"Yes, Revision B is the latest version. Please pay close attention to the center bore tolerance.","vi":"Đúng rồi, Bản B là mới nhất. Nhớ chú ý kỹ dung sai của lỗ tâm nhé."},{"role":"A","speakerName":"Thợ CNC (Hùng)","en":"Got it. It states 25 millimeters plus or minus 0.02, right? Also, what about the edge chamfer?","vi":"Rõ rồi. Bản vẽ ghi 25 mm cộng trừ 0.02 đúng không? Còn phần vát mép cạnh thì sao ạ?"},{"role":"B","speakerName":"Kỹ sư thiết kế (David)","en":"Correct, 25 plus or minus 0.02. Please apply a 0.5-millimeter chamfer on both ends for safe assembly.","vi":"Chính xác, 25 ± 0.02. Hãy vát mép 0.5 mm ở cả hai đầu để lắp ráp an toàn nhé."}]', '{"title":"Vai A · Kỹ thuật viên Gia công CNC","goal":"Kiểm tra và xác nhận lại toàn bộ kích thước, dung sai và yêu cầu vát mép trước khi chạy máy.","tasks":["Hỏi xác nhận phiên bản bản vẽ và vật liệu phôi.","Đọc lại ít nhất 2 thông số có dung sai để đối chiếu.","Đề xuất kiểm tra mẫu đầu tiên (first-article inspection) bằng thước cặp."]}', '{"title":"Vai B · Kỹ sư Thiết kế / QC","goal":"Giải thích rõ các vị trí dung sai chặt và tiêu chuẩn nghiệm thu sản phẩm.","tasks":["Xác nhận phiên bản bản vẽ hợp lệ.","Làm rõ yêu cầu độ nhám bề mặt và vát mép lắp ráp.","Thống nhất số lượng mẫu kiểm tra đầu ca."]}', '[{"id":"terminology","criterion":"Thuật ngữ chuyên ngành","description":"Dùng đúng và tự nhiên các từ vựng, cụm từ kỹ thuật/nghề nghiệp của tình huống.","maxScore":5},{"id":"clarity","criterion":"Phát âm & Độ rõ ý","description":"Phát âm từ khóa quan trọng (thông số, lỗi, hành động) dễ hiểu với bạn cùng luyện.","maxScore":5},{"id":"task_completion","criterion":"Xử lý đúng trọng tâm","description":"Hoàn thành đầy đủ nhiệm vụ của vai đóng và phản hồi sát câu hỏi đối phương.","maxScore":5},{"id":"interaction","criterion":"Phản xạ & Xác nhận thông tin","description":"Biết hỏi lại khi chưa rõ, xác nhận thông số/thời hạn để tránh hiểu nhầm công việc.","maxScore":5},{"id":"professionalism","criterion":"Thái độ nghề nghiệp","description":"Giữ giọng điệu lịch sự, hợp tác và đúng quy tắc an toàn/văn hóa nơi làm việc.","maxScore":5}]', 'Cao Anh Nhựt', 'GV chuyên môn Khoa Cơ khí · VSVC', 'Biên soạn nội bộ dựa trên giáo trình Đọc bản vẽ kỹ thuật Cơ khí VSVC.', 2, '2026-11-17T00:00:00.000Z');
INSERT OR REPLACE INTO career_scenarios (id, slug, title, major, target_audience, level, summary, duration_minutes, is_free, vocab_json, phrases_json, dialogue_json, role_a_json, role_b_json, rubric_json, author_name, reviewed_by_teacher, source_attribution, display_order, created_at) VALUES ('csc_3', 'ban-giao-ca-va-kiem-tra-chat-luong-qc', 'Bàn giao ca sản xuất & kiểm tra chất lượng (QC)', 'Cơ khí', 'Học sinh, sinh viên Cao đẳng nghề • Trung cấp nghề • GDNN - GDTX', 'Cơ bản (A2)', 'Báo cáo số lượng đạt chuẩn, tỷ lệ phế phẩm và các lưu ý bảo dưỡng dao cắt khi bàn giao ca cho đồng nghiệp hoặc tổ trưởng.', 15, 1, '[{"word":"handover","phonetic":"/ˈhændˌoʊ.vər/","pos":"noun","meaning":"bàn giao ca làm việc","example":"Let''s do a quick shift handover near Line 1."},{"word":"defect rate","phonetic":"/ˈdiː.fekt reɪt/","pos":"noun","meaning":"tỷ lệ lỗi / phế phẩm","example":"Our defect rate stayed below one percent today."},{"word":"cutting tool","phonetic":"/ˈkʌt.ɪŋ tuːl/","pos":"noun","meaning":"dao cắt gia công","example":"The cutting tool was replaced at 2 PM."},{"word":"inspect","phonetic":"/ɪnˈspekt/","pos":"verb","meaning":"kiểm tra, thanh tra","example":"Please inspect every tenth piece for scratches."}]', '[{"en":"During this shift, we completed 180 units with only 2 defects.","vi":"Trong ca này, chúng tôi hoàn thành 180 sản phẩm và chỉ có 2 lỗi.","context":"Báo cáo sản lượng và chất lượng đầu buổi bàn giao."},{"en":"Please keep an eye on the coolant level after 10 PM.","vi":"Nhớ để ý mực dung dịch làm mát sau 10 giờ tối nhé.","context":"Nhắc lưu ý bảo trì cho ca sau."}]', '[{"role":"A","speakerName":"Trưởng ca sáng","en":"Hi Minh, ready for the shift handover? We completed 180 brackets with 2 rejected parts.","vi":"Chào Minh, sẵn sàng bàn giao ca chưa? Ca sáng xong 180 chi tiết, chỉ loại 2 chiếc lỗi."},{"role":"B","speakerName":"Trưởng ca chiều","en":"Got it. What caused the 2 defects, and did you change the cutting insert?","vi":"Mình nắm rồi. Hai chiếc lỗi do đâu vậy, và bạn đã thay mảnh dao cắt chưa?"},{"role":"A","speakerName":"Trưởng ca sáng","en":"Minor surface scratches from a worn insert. I already installed a fresh cutting tool at 1:30 PM.","vi":"Bị xước nhẹ bề mặt do dao mòn. Mình đã thay dao mới lúc 1 giờ 30 chiều rồi."},{"role":"B","speakerName":"Trưởng ca chiều","en":"Great, I will monitor the coolant level and inspect every tenth piece.","vi":"Tuyệt, ca chiều mình sẽ theo dõi nước làm mát và kiểm tra mỗi 10 sản phẩm."}]', '{"title":"Vai A · Người giao ca","goal":"Bàn giao đầy đủ số lượng đạt, số lượng lỗi, tình trạng dao cắt và vật tư còn lại.","tasks":["Báo cáo tổng sản lượng và số sản phẩm không đạt.","Nêu nguyên nhân lỗi và các thay đổi thiết bị đã làm.","Dặn dò 1 điểm cần theo dõi ở ca tiếp theo."]}', '{"title":"Vai B · Người nhận ca","goal":"Hỏi xác nhận các vấn đề còn tồn đọng để vận hành ca mới an toàn và ổn định.","tasks":["Xác nhận số liệu và hỏi nguyên nhân hàng lỗi.","Kiểm tra trạng thái dao cắt, dầu làm mát hoặc máy đo.","Cam kết tần suất kiểm tra QC trong ca."]}', '[{"id":"terminology","criterion":"Thuật ngữ chuyên ngành","description":"Dùng đúng và tự nhiên các từ vựng, cụm từ kỹ thuật/nghề nghiệp của tình huống.","maxScore":5},{"id":"clarity","criterion":"Phát âm & Độ rõ ý","description":"Phát âm từ khóa quan trọng (thông số, lỗi, hành động) dễ hiểu với bạn cùng luyện.","maxScore":5},{"id":"task_completion","criterion":"Xử lý đúng trọng tâm","description":"Hoàn thành đầy đủ nhiệm vụ của vai đóng và phản hồi sát câu hỏi đối phương.","maxScore":5},{"id":"interaction","criterion":"Phản xạ & Xác nhận thông tin","description":"Biết hỏi lại khi chưa rõ, xác nhận thông số/thời hạn để tránh hiểu nhầm công việc.","maxScore":5},{"id":"professionalism","criterion":"Thái độ nghề nghiệp","description":"Giữ giọng điệu lịch sự, hợp tác và đúng quy tắc an toàn/văn hóa nơi làm việc.","maxScore":5}]', 'Vũ Tiến Anh', 'GV chuyên môn Khoa Cơ khí · VSVC', 'Biên soạn dựa trên quy trình bàn giao ca xưởng thực hành VSVC.', 3, '2026-11-17T00:00:00.000Z');
INSERT OR REPLACE INTO career_scenarios (id, slug, title, major, target_audience, level, summary, duration_minutes, is_free, vocab_json, phrases_json, dialogue_json, role_a_json, role_b_json, rubric_json, author_name, reviewed_by_teacher, source_attribution, display_order, created_at) VALUES ('csc_4', 'phong-van-ky-thuat-vien-co-khi', 'Phỏng vấn thực tập & tuyển dụng Kỹ thuật viên Cơ khí', 'Cơ khí', 'Học sinh, sinh viên Cao đẳng nghề • Trung cấp nghề • GDNN - GDTX', 'Trung bình (B1)', 'Luyện trả lời phỏng vấn bằng tiếng Anh về kinh nghiệm thực hành xưởng, nguyên tắc an toàn lao động và cách xử lý khi máy gặp lỗi.', 20, 0, '[{"word":"safety gear","phonetic":"/ˈseɪf.ti ɡɪr/","pos":"noun","meaning":"đồ bảo hộ lao động (PPE)","example":"I always wear proper safety gear before entering the workshop."},{"word":"preventive maintenance","phonetic":"/prɪˈven.tɪv ˈmeɪn.tən.əns/","pos":"noun","meaning":"bảo trì phòng ngừa","example":"Preventive maintenance helps reduce unexpected breakdowns."},{"word":"hands-on experience","phonetic":"/ˌhændzˈɑːn ɪkˈspɪr.i.əns/","pos":"noun","meaning":"kinh nghiệm thực hành trực tiếp","example":"I gained hands-on experience with milling and lathe machines at college."}]', '[{"en":"During my vocational training, I practiced operating both manual lathes and CNC machines.","vi":"Trong quá trình học nghề, tôi đã thực hành vận hành cả máy tiện cơ và máy CNC.","context":"Giới thiệu năng lực thực hành khi phỏng vấn."},{"en":"When I spot an abnormal noise, I press the emergency stop and notify my supervisor.","vi":"Khi nghe thấy tiếng ồn bất thường, tôi bấm nút dừng khẩn cấp và báo cho giám sát.","context":"Trả lời câu hỏi tình huống về an toàn xưởng."}]', '[{"role":"A","speakerName":"Nhà tuyển dụng","en":"Welcome! Can you tell me briefly about your hands-on experience in mechanical workshops?","vi":"Chào bạn! Bạn có thể chia sẻ ngắn gọn về kinh nghiệm thực hành xưởng cơ khí của mình không?"},{"role":"B","speakerName":"Ứng viên","en":"Certainly. At Vietnam-Singapore Vocational College, I practiced reading blueprints, operating lathes, and checking tolerances with calipers.","vi":"Dạ vâng. Tại Trường CĐ nghề Việt Nam - Singapore, em đã thực hành đọc bản vẽ, vận hành máy tiện và kiểm tra dung sai bằng thước cặp."},{"role":"A","speakerName":"Nhà tuyển dụng","en":"What would you do first if a machine makes a loud knocking sound during a cycle?","vi":"Bạn sẽ làm gì đầu tiên nếu máy phát ra tiếng gõ lớn khi đang chạy chu trình?"},{"role":"B","speakerName":"Ứng viên","en":"First, I would hit the emergency stop button to ensure safety, turn off the power if needed, and immediately inform the shift leader.","vi":"Đầu tiên, em sẽ nhấn nút dừng khẩn cấp để đảm bảo an toàn, ngắt nguồn nếu cần và báo ngay cho trưởng ca."}]', '{"title":"Vai A · Nhà tuyển dụng / Kỹ sư trưởng","goal":"Đánh giá kỹ năng thực hành, nhận thức an toàn và khả năng giao tiếp tiếng Anh nghề của ứng viên.","tasks":["Hỏi về quá trình học và máy móc ứng viên từng thao tác.","Đặt 1 câu hỏi tình huống xử lý sự cố hoặc an toàn lao động.","Cho ứng viên cơ hội hỏi lại về môi trường làm việc."]}', '{"title":"Vai B · Ứng viên Kỹ thuật viên","goal":"Trình bày tự tin kinh nghiệm thực hành xưởng và tư duy tuân thủ an toàn.","tasks":["Giới thiệu ngành học và ít nhất 2 kỹ năng thực hành cụ thể.","Trả lời rõ ràng quy trình xử lý sự cố theo ưu tiên an toàn.","Đặt 1 câu hỏi thông minh về đào tạo hội nhập hoặc ca làm việc."]}', '[{"id":"terminology","criterion":"Thuật ngữ chuyên ngành","description":"Dùng đúng và tự nhiên các từ vựng, cụm từ kỹ thuật/nghề nghiệp của tình huống.","maxScore":5},{"id":"clarity","criterion":"Phát âm & Độ rõ ý","description":"Phát âm từ khóa quan trọng (thông số, lỗi, hành động) dễ hiểu với bạn cùng luyện.","maxScore":5},{"id":"task_completion","criterion":"Xử lý đúng trọng tâm","description":"Hoàn thành đầy đủ nhiệm vụ của vai đóng và phản hồi sát câu hỏi đối phương.","maxScore":5},{"id":"interaction","criterion":"Phản xạ & Xác nhận thông tin","description":"Biết hỏi lại khi chưa rõ, xác nhận thông số/thời hạn để tránh hiểu nhầm công việc.","maxScore":5},{"id":"professionalism","criterion":"Thái độ nghề nghiệp","description":"Giữ giọng điệu lịch sự, hợp tác và đúng quy tắc an toàn/văn hóa nơi làm việc.","maxScore":5}]', 'Bùi Tấn Lộc', 'GV hướng dẫn Nguyễn Xuân Tùng · VSVC', 'Biên soạn theo bộ câu hỏi phỏng vấn doanh nghiệp tuyển dụng SV CĐ nghề.', 4, '2026-11-17T00:00:00.000Z');
INSERT OR REPLACE INTO career_scenarios (id, slug, title, major, target_audience, level, summary, duration_minutes, is_free, vocab_json, phrases_json, dialogue_json, role_a_json, role_b_json, rubric_json, author_name, reviewed_by_teacher, source_attribution, display_order, created_at) VALUES ('csc_5', 'kiem-tra-mach-va-bao-loi-thiet-bi-dien', 'Kiểm tra mạch điều khiển & báo lỗi thiết bị điện', 'Điện - Điện tử', 'Học sinh, sinh viên Cao đẳng nghề • Trung cấp nghề • GDNN - GDTX', 'Cơ bản (A2)', 'Đo kiểm điện áp, phát hiện lỗi rơ-le nhiệt / quá tải cầu dao và báo cáo thông số đo cho kỹ sư phụ trách.', 15, 1, '[{"word":"multimeter","phonetic":"/ˌmʌl.tiˈmiː.tər/","pos":"noun","meaning":"đồng hồ vạn năng","example":"Use a multimeter to measure the output voltage."},{"word":"circuit breaker","phonetic":"/ˈsɜːr.kɪt ˈbreɪ.kər/","pos":"noun","meaning":"cầu dao tự động (CB / aptomat)","example":"The main circuit breaker tripped twice this morning."},{"word":"overload relay","phonetic":"/ˌoʊ.vərˈloʊd ˈriː.leɪ/","pos":"noun","meaning":"rơ-le nhiệt quá tải","example":"Check if the overload relay needs resetting."},{"word":"short circuit","phonetic":"/ʃɔːrt ˈsɜːr.kɪt/","pos":"noun","meaning":"ngắn mạch, chập mạch","example":"Damaged insulation can cause a short circuit."},{"word":"grounding","phonetic":"/ˈɡraʊn.dɪŋ/","pos":"noun","meaning":"tiếp địa, nối đất an toàn","example":"Verify proper grounding before powering up the panel."}]', '[{"en":"The circuit breaker tripped due to an overload on Phase B.","vi":"Aptomat bị nhảy do quá tải ở Pha B.","context":"Báo cáo nguyên nhân ngắt mạch chính xác."},{"en":"I measured 220 volts at the input terminal, but zero volts at the motor.","vi":"Tôi đo được 220 vôn ở đầu vào, nhưng 0 vôn ở động cơ.","context":"Trình bày kết quả đo đồng hồ vạn năng để khoanh vùng lỗi."}]', '[{"role":"A","speakerName":"Kỹ thuật viên Điện","en":"Hi Kevin, the conveyor motor stopped because the circuit breaker tripped again.","vi":"Chào Kevin, động cơ băng tải dừng vì aptomat vừa nhảy lại rồi."},{"role":"B","speakerName":"Kỹ sư trưởng","en":"Did you check the voltage with your multimeter after locking out the power?","vi":"Bạn đã khóa nguồn an toàn và đo lại điện áp bằng đồng hồ vạn năng chưa?"},{"role":"A","speakerName":"Kỹ thuật viên Điện","en":"Yes, the input terminal reads 380 volts across all three phases, and there is no short circuit.","vi":"Rồi ạ, đầu vào đủ 380 vôn cả 3 pha, và không bị ngắn mạch."},{"role":"B","speakerName":"Kỹ sư trưởng","en":"Good. Check the overload relay and inspect the motor current once we restart.","vi":"Tốt. Hãy kiểm tra rơ-le quá tải và theo dõi dòng động cơ khi khởi động lại nhé."}]', '{"title":"Vai A · Kỹ thuật viên Bảo trì Điện","goal":"Báo cáo tình trạng nhảy CB, trình bày kết quả đo điện áp/điện trở và xác nhận không có chập mạch.","tasks":["Mô tả hiện tượng thiết bị ngừng hoạt động.","Đọc rõ thông số đo được (Volt / Ampere / Ohm) bằng đồng hồ vạn năng.","Xác nhận đã kiểm tra tiếp địa trước khi đóng điện lại."]}', '{"title":"Vai B · Kỹ sư Giám sát Điện","goal":"Hướng dẫn khoanh vùng điểm đứt mạch và nhắc quy trình an toàn trước khi cấp nguồn.","tasks":["Hỏi xác nhận đã cô lập nguồn điện trước khi đo kiểm chưa.","Yêu cầu đọc thông số 3 pha hoặc rơ-le nhiệt.","Quyết định cho phép reset hoặc thay linh kiện."]}', '[{"id":"terminology","criterion":"Thuật ngữ chuyên ngành","description":"Dùng đúng và tự nhiên các từ vựng, cụm từ kỹ thuật/nghề nghiệp của tình huống.","maxScore":5},{"id":"clarity","criterion":"Phát âm & Độ rõ ý","description":"Phát âm từ khóa quan trọng (thông số, lỗi, hành động) dễ hiểu với bạn cùng luyện.","maxScore":5},{"id":"task_completion","criterion":"Xử lý đúng trọng tâm","description":"Hoàn thành đầy đủ nhiệm vụ của vai đóng và phản hồi sát câu hỏi đối phương.","maxScore":5},{"id":"interaction","criterion":"Phản xạ & Xác nhận thông tin","description":"Biết hỏi lại khi chưa rõ, xác nhận thông số/thời hạn để tránh hiểu nhầm công việc.","maxScore":5},{"id":"professionalism","criterion":"Thái độ nghề nghiệp","description":"Giữ giọng điệu lịch sự, hợp tác và đúng quy tắc an toàn/văn hóa nơi làm việc.","maxScore":5}]', 'Võ Gia Như', 'GV chuyên môn Khoa Điện - Điện tử · VSVC', 'Biên soạn từ bài thực hành đo lường & sửa chữa mạch điện VSVC.', 5, '2026-11-17T00:00:00.000Z');
INSERT OR REPLACE INTO career_scenarios (id, slug, title, major, target_audience, level, summary, duration_minutes, is_free, vocab_json, phrases_json, dialogue_json, role_a_json, role_b_json, rubric_json, author_name, reviewed_by_teacher, source_attribution, display_order, created_at) VALUES ('csc_6', 'quy-trinh-an-toan-tu-dien-loto', 'Hướng dẫn vận hành & quy trình khóa an toàn tủ điện (LOTO)', 'Điện - Điện tử', 'Học sinh, sinh viên Cao đẳng nghề • Trung cấp nghề • GDNN - GDTX', 'Trung bình (B1)', 'Giải thích và kiểm tra chéo các bước Lockout/Tagout (khóa và gắn thẻ cảnh báo) trước khi bảo trì tủ điện công nghiệp.', 15, 1, '[{"word":"lockout / tagout","phonetic":"/ˈlɑːk.aʊt ˈtæɡ.aʊt/","pos":"noun","meaning":"quy trình khóa nguồn và gắn thẻ cảnh báo (LOTO)","example":"Never skip lockout/tagout when servicing high-voltage cabinets."},{"word":"control cabinet","phonetic":"/kənˈtroʊl ˈkæb.ɪ.nət/","pos":"noun","meaning":"tủ điện điều khiển","example":"Lock the main switch inside the control cabinet."},{"word":"insulated gloves","phonetic":"/ˈɪn.sjə.leɪ.tɪd ɡlʌvz/","pos":"noun","meaning":"găng tay cách điện","example":"Put on insulated gloves rated for 1,000 volts."}]', '[{"en":"Before opening the control cabinet, make sure the main isolator is switched off and locked.","vi":"Trước khi mở tủ điều khiển, hãy đảm bảo cầu dao tổng đã tắt và được khóa lại.","context":"Nhắc bước an toàn bắt buộc trước khi thao tác."},{"en":"Verify zero energy with a voltage tester before touching any terminals.","vi":"Kiểm tra không còn điện bằng bút thử/máy đo trước khi chạm vào các cực nối.","context":"Bước kiểm tra không điện (Test before touch)."}]', '[{"role":"A","speakerName":"Kỹ thuật viên hướng dẫn","en":"Before we open Control Cabinet B, can you walk me through our lockout/tagout steps?","vi":"Trước khi mở Tủ điều khiển B, bạn nhắc lại giúp mình các bước khóa và gắn thẻ LOTO nhé?"},{"role":"B","speakerName":"Học viên thực tập","en":"Sure. First, I switch off the main breaker, attach my personal padlock, and place the warning tag.","vi":"Dạ vâng. Đầu tiên em tắt aptomat tổng, móc khóa cá nhân của mình và gắn thẻ cảnh báo."},{"role":"A","speakerName":"Kỹ thuật viên hướng dẫn","en":"Great. What is the critical step right after attaching the lock and tag?","vi":"Chuẩn rồi. Bước tối quan trọng ngay sau khi khóa và gắn thẻ là gì?"},{"role":"B","speakerName":"Học viên thực tập","en":"I wear insulated gloves and test all terminals with a multimeter to verify zero voltage.","vi":"Em đeo găng tay cách điện và đo kiểm tất cả các cực bằng đồng hồ vạn năng để xác nhận điện áp bằng 0."}]', '{"title":"Vai A · Giám sát An toàn Điện","goal":"Kiểm tra xem đồng nghiệp mới có nắm chắc trình tự LOTO và PPE không.","tasks":["Hỏi 3 bước chính của quy trình LOTO.","Kiểm tra trang bị bảo hộ (găng tay cách điện, giày cách điện).","Xác nhận người giữ chìa khóa cá nhân."]}', '{"title":"Vai B · Kỹ thuật viên Thực tập","goal":"Trình bày chính xác từng bước ngắt nguồn, khóa thẻ và kiểm tra không điện.","tasks":["Nêu rõ trình tự: Tắt tải -> Ngắt cầu dao -> Khóa & Gắn thẻ -> Đo kiểm không điện.","Nêu đúng đồ bảo hộ sử dụng.","Hỏi lại vị trí tiếp địa hoặc sơ đồ tủ nếu cần."]}', '[{"id":"terminology","criterion":"Thuật ngữ chuyên ngành","description":"Dùng đúng và tự nhiên các từ vựng, cụm từ kỹ thuật/nghề nghiệp của tình huống.","maxScore":5},{"id":"clarity","criterion":"Phát âm & Độ rõ ý","description":"Phát âm từ khóa quan trọng (thông số, lỗi, hành động) dễ hiểu với bạn cùng luyện.","maxScore":5},{"id":"task_completion","criterion":"Xử lý đúng trọng tâm","description":"Hoàn thành đầy đủ nhiệm vụ của vai đóng và phản hồi sát câu hỏi đối phương.","maxScore":5},{"id":"interaction","criterion":"Phản xạ & Xác nhận thông tin","description":"Biết hỏi lại khi chưa rõ, xác nhận thông số/thời hạn để tránh hiểu nhầm công việc.","maxScore":5},{"id":"professionalism","criterion":"Thái độ nghề nghiệp","description":"Giữ giọng điệu lịch sự, hợp tác và đúng quy tắc an toàn/văn hóa nơi làm việc.","maxScore":5}]', 'Võ Gia Như', 'GV chuyên môn Khoa Điện - Điện tử · VSVC', 'Biên soạn từ tài liệu An toàn điện công nghiệp VSVC.', 6, '2026-11-17T00:00:00.000Z');
INSERT OR REPLACE INTO career_scenarios (id, slug, title, major, target_audience, level, summary, duration_minutes, is_free, vocab_json, phrases_json, dialogue_json, role_a_json, role_b_json, rubric_json, author_name, reviewed_by_teacher, source_attribution, display_order, created_at) VALUES ('csc_7', 'doc-datasheet-va-thay-the-linh-kien-dien-tu', 'Đọc hiểu datasheet linh kiện & đề xuất thay thế cảm biến/tụ điện', 'Điện - Điện tử', 'Học sinh, sinh viên Cao đẳng nghề • Trung cấp nghề • GDNN - GDTX', 'Khá (B2)', 'So sánh thông số kỹ thuật từ datasheet (điện áp định mức, dải nhiệt độ, chân kết nối pinout) khi linh kiện cũ ngừng sản xuất.', 15, 0, '[{"word":"rated voltage","phonetic":"/ˈreɪ.tɪd ˈvoʊl.tɪdʒ/","pos":"noun","meaning":"điện áp định mức","example":"Never exceed the capacitor''s rated voltage of 25 volts."},{"word":"pinout","phonetic":"/ˈpɪn.aʊt/","pos":"noun","meaning":"sơ đồ chân linh kiện","example":"Check the pinout diagram carefully before soldering."},{"word":"compatible","phonetic":"/kəmˈpæt.ə.bəl/","pos":"adjective","meaning":"tương thích, thay thế được","example":"This 24V proximity sensor is fully compatible with our PLC input."}]', '[{"en":"The original model is out of stock, so I found a compatible replacement.","vi":"Mã gốc đã hết hàng, nên tôi đã tìm một linh kiện thay thế tương thích.","context":"Đề xuất linh kiện thay thế với quản lý."},{"en":"Both share the same 24-volt DC supply and NPN output pinout.","vi":"Cả hai đều dùng nguồn 24V DC và sơ đồ chân ngõ ra NPN giống nhau.","context":"Chứng minh sự tương thích kỹ thuật từ datasheet."}]', '[{"role":"A","speakerName":"Kỹ thuật viên Điện tử","en":"Ms. Linh, the original optical sensor is discontinued. I checked the datasheet and found a compatible alternative.","vi":"Chị Linh ơi, cảm biến quang mã cũ đã ngừng sản xuất. Em xem datasheet và tìm được mã thay thế tương thích rồi."},{"role":"B","speakerName":"Trưởng nhóm R&D","en":"Nice work. Does it match our 24V DC rated voltage and NPN output requirement?","vi":"Tốt lắm. Nó có khớp mức điện áp 24V DC và ngõ ra NPN bên mình yêu cầu không?"},{"role":"A","speakerName":"Kỹ thuật viên Điện tử","en":"Yes, both the rated voltage and the 3-pin M12 pinout are identical, and its operating temperature reaches 70 degrees Celsius.","vi":"Dạ có, cả điện áp định mức lẫn sơ đồ 3 chân M12 đều giống hệt, và dải nhiệt hoạt động lên tới 70 độ C."}]', '{"title":"Vai A · Kỹ thuật viên Phần cứng","goal":"Chứng minh linh kiện đề xuất đạt chuẩn thông số để thay thế an toàn.","tasks":["Nêu lý do cần linh kiện thay thế.","Đối chiếu 3 thông số từ datasheet (điện áp, sơ đồ chân, nhiệt độ/tín hiệu).","Đề xuất đặt mẫu thử nghiệm 2 chiếc trước khi mua lô lớn."]}', '{"title":"Vai B · Kỹ sư R&D / Mua hàng kỹ thuật","goal":"Kiểm tra chéo khả năng tương thích và thời gian giao hàng.","tasks":["Hỏi cụ thể về điện áp định mức và loại ngõ ra (NPN/PNP).","Kiểm tra kích thước lắp đặt cơ khí và thời gian đặt hàng."]}', '[{"id":"terminology","criterion":"Thuật ngữ chuyên ngành","description":"Dùng đúng và tự nhiên các từ vựng, cụm từ kỹ thuật/nghề nghiệp của tình huống.","maxScore":5},{"id":"clarity","criterion":"Phát âm & Độ rõ ý","description":"Phát âm từ khóa quan trọng (thông số, lỗi, hành động) dễ hiểu với bạn cùng luyện.","maxScore":5},{"id":"task_completion","criterion":"Xử lý đúng trọng tâm","description":"Hoàn thành đầy đủ nhiệm vụ của vai đóng và phản hồi sát câu hỏi đối phương.","maxScore":5},{"id":"interaction","criterion":"Phản xạ & Xác nhận thông tin","description":"Biết hỏi lại khi chưa rõ, xác nhận thông số/thời hạn để tránh hiểu nhầm công việc.","maxScore":5},{"id":"professionalism","criterion":"Thái độ nghề nghiệp","description":"Giữ giọng điệu lịch sự, hợp tác và đúng quy tắc an toàn/văn hóa nơi làm việc.","maxScore":5}]', 'Võ Gia Như', 'GV chuyên môn Khoa Điện - Điện tử · VSVC', 'Biên soạn từ giáo trình Linh kiện điện tử & Mạch ứng dụng.', 7, '2026-11-17T00:00:00.000Z');
INSERT OR REPLACE INTO career_scenarios (id, slug, title, major, target_audience, level, summary, duration_minutes, is_free, vocab_json, phrases_json, dialogue_json, role_a_json, role_b_json, rubric_json, author_name, reviewed_by_teacher, source_attribution, display_order, created_at) VALUES ('csc_8', 'phong-van-ky-thuat-vien-bao-tri-dien', 'Phỏng vấn Kỹ thuật viên Bảo trì Điện - Tự động hóa', 'Điện - Điện tử', 'Học sinh, sinh viên Cao đẳng nghề • Trung cấp nghề • GDNN - GDTX', 'Trung bình (B1)', 'Trả lời phỏng vấn về kỹ năng đọc sơ đồ mạch điện, đấu nối tủ PLC cơ bản và xử lý lỗi cảm biến trên dây chuyền.', 20, 1, '[{"word":"wiring diagram","phonetic":"/ˈwaɪr.ɪŋ ˈdaɪ.ə.ɡræm/","pos":"noun","meaning":"sơ đồ đấu dây","example":"I can read industrial wiring diagrams and troubleshoot relay panels."},{"word":"troubleshoot","phonetic":"/ˈtrʌb.əl.ʃuːt/","pos":"verb","meaning":"tìm và khắc phục sự cố","example":"We troubleshoot PLC input errors step by step."}]', '[{"en":"I am comfortable reading wiring diagrams and using a multimeter to isolate faults.","vi":"Tôi thành thạo đọc sơ đồ đấu dây và dùng đồng hồ vạn năng để khoanh vùng lỗi.","context":"Khẳng định điểm mạnh chuyên môn khi phỏng vấn."}]', '[{"role":"A","speakerName":"Quản lý Bảo trì","en":"How would you troubleshoot a conveyor that refuses to start when the green button is pressed?","vi":"Bạn sẽ tìm lỗi thế nào nếu băng tải không chạy khi nhấn nút xanh?"},{"role":"B","speakerName":"Ứng viên","en":"I would follow the wiring diagram: first check the power indicator and emergency stop button, then test the start pushbutton and contactor coil with a multimeter.","vi":"Em sẽ theo sơ đồ đấu dây: trước tiên kiểm tra đèn nguồn và nút dừng khẩn cấp, sau đó đo kiểm nút nhấn chạy và cuộn hút contactor bằng đồng hồ vạn năng."}]', '{"title":"Vai A · Quản lý Bảo trì","goal":"Đánh giá tư duy logic tìm lỗi điện và thái độ tuân thủ an toàn.","tasks":["Hỏi kinh nghiệm đọc sơ đồ mạch / PLC ở trường.","Đưa ra tình huống băng tải không chạy và xem cách ứng viên khoanh vùng."]}', '{"title":"Vai B · Ứng viên Bảo trì Điện","goal":"Trả lời mạch lạc theo từng bước kiểm tra từ nguồn đến tải.","tasks":["Nhấn mạnh thói quen kiểm tra an toàn trước khi đo.","Nêu trình tự kiểm tra logic (Nguồn -> Nút dừng khẩn -> Rơ-le/Contactor -> Động cơ)."]}', '[{"id":"terminology","criterion":"Thuật ngữ chuyên ngành","description":"Dùng đúng và tự nhiên các từ vựng, cụm từ kỹ thuật/nghề nghiệp của tình huống.","maxScore":5},{"id":"clarity","criterion":"Phát âm & Độ rõ ý","description":"Phát âm từ khóa quan trọng (thông số, lỗi, hành động) dễ hiểu với bạn cùng luyện.","maxScore":5},{"id":"task_completion","criterion":"Xử lý đúng trọng tâm","description":"Hoàn thành đầy đủ nhiệm vụ của vai đóng và phản hồi sát câu hỏi đối phương.","maxScore":5},{"id":"interaction","criterion":"Phản xạ & Xác nhận thông tin","description":"Biết hỏi lại khi chưa rõ, xác nhận thông số/thời hạn để tránh hiểu nhầm công việc.","maxScore":5},{"id":"professionalism","criterion":"Thái độ nghề nghiệp","description":"Giữ giọng điệu lịch sự, hợp tác và đúng quy tắc an toàn/văn hóa nơi làm việc.","maxScore":5}]', 'Bùi Tấn Lộc', 'GV chuyên môn Khoa Điện - Điện tử · VSVC', 'Biên soạn từ câu hỏi tuyển dụng thực tế các khu công nghiệp VSIP.', 8, '2026-11-17T00:00:00.000Z');
INSERT OR REPLACE INTO career_scenarios (id, slug, title, major, target_audience, level, summary, duration_minutes, is_free, vocab_json, phrases_json, dialogue_json, role_a_json, role_b_json, rubric_json, author_name, reviewed_by_teacher, source_attribution, display_order, created_at) VALUES ('csc_9', 'daily-standup-va-bao-cao-tien-do-bug-it', 'Họp Daily Stand-up & báo cáo tiến độ / bug với team quốc tế', 'Tin học', 'Học sinh, sinh viên Cao đẳng nghề • Trung cấp nghề • GDNN - GDTX', 'Cơ bản (A2)', 'Tình huống giao tiếp phổ biến nhất ngành CNTT: báo cáo 3 ý trong buổi họp sáng (hôm qua làm gì, hôm nay làm gì, đang gặp blocker gì).', 15, 1, '[{"word":"blocker","phonetic":"/ˈblɑː.kər/","pos":"noun","meaning":"vướng mắc làm chậm tiến độ công việc","example":"My main blocker right now is missing API credentials."},{"word":"reproduce","phonetic":"/ˌriː.prəˈduːs/","pos":"verb","meaning":"tái hiện lại lỗi (bug)","example":"I can reproduce the login bug on mobile Safari."},{"word":"pull request","phonetic":"/pʊl rɪˈkwest/","pos":"noun","meaning":"yêu cầu gộp mã nguồn (PR)","example":"I submitted a pull request for the dashboard filter."},{"word":"deploy","phonetic":"/dɪˈplɔɪ/","pos":"verb","meaning":"triển khai phần mềm lên môi trường chạy","example":"We plan to deploy the patch to staging this afternoon."}]', '[{"en":"Yesterday I finished the login validation and opened a pull request.","vi":"Hôm qua tôi đã xong phần kiểm tra đăng nhập và tạo pull request.","context":"Báo cáo phần việc đã hoàn thành."},{"en":"Today I will work on fixing the pagination bug on mobile.","vi":"Hôm nay tôi sẽ xử lý lỗi phân trang trên điện thoại.","context":"Báo cáo kế hoạch trong ngày."},{"en":"I am currently blocked by a 500 error from the staging API.","vi":"Hiện tại tôi đang bị vướng lỗi 500 từ API môi trường staging.","context":"Nêu rõ blocker để được hỗ trợ ngay."}]', '[{"role":"A","speakerName":"Tech Lead (Alex)","en":"Morning Loc, it''s your turn for the stand-up update. How is the student profile module going?","vi":"Chào Lộc, tới lượt bạn cập nhật stand-up nhé. Module hồ sơ sinh viên tiến triển sao rồi?"},{"role":"B","speakerName":"Developer (Lộc)","en":"Morning everyone. Yesterday I completed the profile form validation and submitted a pull request.","vi":"Chào mọi người. Hôm qua mình đã làm xong phần kiểm tra biểu mẫu hồ sơ và gửi pull request."},{"role":"B","speakerName":"Developer (Lộc)","en":"Today I will add unit tests for age-group filtering. I have one small blocker: I need test access to the staging database.","vi":"Hôm nay mình sẽ viết unit test cho bộ lọc nhóm tuổi. Có một vướng mắc nhỏ là mình cần quyền truy cập dữ liệu mẫu trên staging."},{"role":"A","speakerName":"Tech Lead (Alex)","en":"Got it. I will grant your staging read-only role right after this call and review your PR by noon.","vi":"Đã rõ. Mình sẽ cấp quyền đọc staging ngay sau cuộc gọi này và duyệt PR của bạn trước trưa nhé."}]', '{"title":"Vai A · Tech Lead / Scrum Master","goal":"Điều phối buổi stand-up ngắn gọn, nắm bắt tiến độ và tháo gỡ blocker cho thành viên.","tasks":["Mời thành viên cập nhật ngắn gọn trong 1–2 phút.","Hỏi chi tiết hơn về blocker để biết cần phối hợp với ai.","Chốt hướng xử lý và thời gian review code."]}', '{"title":"Vai B · Lập trình viên / Thực tập sinh IT","goal":"Báo cáo mạch lạc theo cấu trúc Hôm qua - Hôm nay - Blocker bằng thuật ngữ CNTT chính xác.","tasks":["Nêu rõ tính năng đã xong và trạng thái PR/test.","Nêu kế hoạch công việc hôm nay.","Nêu rõ vấn đề đang vướng mắc (nếu không có thì nói ''No blockers'')."]}', '[{"id":"terminology","criterion":"Thuật ngữ chuyên ngành","description":"Dùng đúng và tự nhiên các từ vựng, cụm từ kỹ thuật/nghề nghiệp của tình huống.","maxScore":5},{"id":"clarity","criterion":"Phát âm & Độ rõ ý","description":"Phát âm từ khóa quan trọng (thông số, lỗi, hành động) dễ hiểu với bạn cùng luyện.","maxScore":5},{"id":"task_completion","criterion":"Xử lý đúng trọng tâm","description":"Hoàn thành đầy đủ nhiệm vụ của vai đóng và phản hồi sát câu hỏi đối phương.","maxScore":5},{"id":"interaction","criterion":"Phản xạ & Xác nhận thông tin","description":"Biết hỏi lại khi chưa rõ, xác nhận thông số/thời hạn để tránh hiểu nhầm công việc.","maxScore":5},{"id":"professionalism","criterion":"Thái độ nghề nghiệp","description":"Giữ giọng điệu lịch sự, hợp tác và đúng quy tắc an toàn/văn hóa nơi làm việc.","maxScore":5}]', 'Bùi Tấn Lộc', 'GV chuyên môn Khoa Tin học đại cương · VSVC', 'Biên soạn theo quy trình Agile/Scrum thực tế tại doanh nghiệp phần mềm.', 9, '2026-11-17T00:00:00.000Z');
INSERT OR REPLACE INTO career_scenarios (id, slug, title, major, target_audience, level, summary, duration_minutes, is_free, vocab_json, phrases_json, dialogue_json, role_a_json, role_b_json, rubric_json, author_name, reviewed_by_teacher, source_attribution, display_order, created_at) VALUES ('csc_10', 'ho-tro-ky-thuat-it-helpdesk-troubleshoot', 'Hỗ trợ kỹ thuật IT Helpdesk & xử lý sự cố mạng qua cuộc gọi', 'Tin học', 'Học sinh, sinh viên Cao đẳng nghề • Trung cấp nghề • GDNN - GDTX', 'Cơ bản (A2)', 'Hướng dẫn người dùng hoặc đồng nghiệp nước ngoài từng bước kiểm tra kết nối Wi-Fi, VPN, xóa cache và ghi nhận ticket sự cố.', 15, 1, '[{"word":"clear browser cache","phonetic":"/klɪr ˈbraʊ.zər kæʃ/","pos":"verb phrase","meaning":"xóa bộ nhớ đệm trình duyệt","example":"Please clear your browser cache and reload the portal."},{"word":"error message","phonetic":"/ˈer.ər ˈmes.ɪdʒ/","pos":"noun","meaning":"thông báo lỗi","example":"Could you read the exact error message on your screen?"},{"word":"remote desktop","phonetic":"/rɪˈmoʊt ˈdesk.tɑːp/","pos":"noun","meaning":"điều khiển máy tính từ xa","example":"May I connect via remote desktop to inspect the driver?"}]', '[{"en":"Could you tell me what error message appears on your screen?","vi":"Bạn có thể đọc giúp tôi thông báo lỗi xuất hiện trên màn hình không?","context":"Thu thập thông tin lỗi trước khi hướng dẫn thao tác."},{"en":"Let''s try disconnecting and reconnecting to the company VPN.","vi":"Hãy thử ngắt kết nối và kết nối lại VPN công ty xem sao.","context":"Đưa ra bước kiểm tra đơn giản theo thứ tự."}]', '[{"role":"A","speakerName":"IT Support","en":"IT Helpdesk speaking, this is Nhut. How can I help you today?","vi":"Bộ phận IT Helpdesk xin nghe, tôi là Nhựt. Tôi có thể hỗ trợ gì cho bạn hôm nay?"},{"role":"B","speakerName":"Nhân viên nước ngoài","en":"Hi Nhut, I cannot access the shared drive since this morning. It says ''Network path not found''.","vi":"Chào Nhựt, từ sáng nay tôi không vào được ổ đĩa dùng chung. Máy báo lỗi ''Không tìm thấy đường dẫn mạng''."},{"role":"A","speakerName":"IT Support","en":"I see. Are you working remotely, and is your VPN icon showing as connected?","vi":"Mình hiểu rồi. Bạn đang làm việc từ xa và biểu tượng VPN có đang hiển thị đã kết nối không?"},{"role":"B","speakerName":"Nhân viên nước ngoài","en":"Oh, the VPN disconnected after my laptop restarted! Let me reconnect and test again.","vi":"Ồ, VPN bị ngắt sau khi laptop mình khởi động lại! Để mình kết nối lại rồi thử xem."}]', '{"title":"Vai A · Nhân viên IT Helpdesk","goal":"Giữ thái độ bình tĩnh, đặt câu hỏi khoanh vùng và hướng dẫn từng bước dễ hiểu cho người không chuyên.","tasks":["Chào hỏi chuyên nghiệp và hỏi chính xác thông báo lỗi.","Hỏi 2 câu kiểm tra nhanh (kết nối mạng/VPN, đã khởi động lại chưa).","Xác nhận sự cố đã giải quyết và đóng ticket."]}', '{"title":"Vai B · Nhân viên gặp sự cố máy tính","goal":"Mô tả rõ triệu chứng lỗi và thực hiện theo hướng dẫn của IT.","tasks":["Mô tả chính xác phần mềm/tính năng bị lỗi và thời điểm bắt đầu.","Thực hiện từng bước IT yêu cầu và phản hồi kết quả."]}', '[{"id":"terminology","criterion":"Thuật ngữ chuyên ngành","description":"Dùng đúng và tự nhiên các từ vựng, cụm từ kỹ thuật/nghề nghiệp của tình huống.","maxScore":5},{"id":"clarity","criterion":"Phát âm & Độ rõ ý","description":"Phát âm từ khóa quan trọng (thông số, lỗi, hành động) dễ hiểu với bạn cùng luyện.","maxScore":5},{"id":"task_completion","criterion":"Xử lý đúng trọng tâm","description":"Hoàn thành đầy đủ nhiệm vụ của vai đóng và phản hồi sát câu hỏi đối phương.","maxScore":5},{"id":"interaction","criterion":"Phản xạ & Xác nhận thông tin","description":"Biết hỏi lại khi chưa rõ, xác nhận thông số/thời hạn để tránh hiểu nhầm công việc.","maxScore":5},{"id":"professionalism","criterion":"Thái độ nghề nghiệp","description":"Giữ giọng điệu lịch sự, hợp tác và đúng quy tắc an toàn/văn hóa nơi làm việc.","maxScore":5}]', 'Bùi Tấn Lộc', 'GV chuyên môn Khoa Tin học đại cương · VSVC', 'Biên soạn dựa trên kịch bản thực hành Hỗ trợ kỹ thuật CNTT VSVC.', 10, '2026-11-17T00:00:00.000Z');
INSERT OR REPLACE INTO career_scenarios (id, slug, title, major, target_audience, level, summary, duration_minutes, is_free, vocab_json, phrases_json, dialogue_json, role_a_json, role_b_json, rubric_json, author_name, reviewed_by_teacher, source_attribution, display_order, created_at) VALUES ('csc_11', 'giai-thich-api-va-demo-tinh-nang-cho-khach-hang', 'Demo tính năng sản phẩm & giải thích luồng API cho khách hàng', 'Tin học', 'Học sinh, sinh viên Cao đẳng nghề • Trung cấp nghề • GDNN - GDTX', 'Khá (B2)', 'Trình bày cách tính năng hoạt động, thời gian phản hồi, bảo mật dữ liệu tối thiểu và tiếp nhận góp ý chỉnh sửa giao diện.', 15, 0, '[{"word":"endpoint","phonetic":"/ˈend.pɔɪnt/","pos":"noun","meaning":"điểm cuối API","example":"This API endpoint validates user permissions before saving."},{"word":"latency","phonetic":"/ˈleɪ.tən.si/","pos":"noun","meaning":"độ trễ phản hồi","example":"Response latency stayed under 120 milliseconds."},{"word":"feedback","phonetic":"/ˈfiːd.bæk/","pos":"noun","meaning":"ý kiến phản hồi","example":"We appreciate your feedback on the filter layout."}]', '[{"en":"Let me walk you through how the matching workflow works from the user side.","vi":"Để tôi giới thiệu qua cách luồng ghép cặp hoạt động ở phía người dùng.","context":"Chuyển sang phần demo màn hình sản phẩm."},{"en":"We enforce age-group isolation directly on the backend API before returning results.","vi":"Chúng tôi áp dụng tách biệt nhóm tuổi trực tiếp ở tầng API máy chủ trước khi trả kết quả.","context":"Giải thích cơ chế bảo mật phía backend cho khách hàng."}]', '[{"role":"A","speakerName":"Lập trình viên Demo","en":"Today I will walk you through our new peer-pairing API and safety guardrails.","vi":"Hôm nay tôi sẽ trình bày qua API ghép cặp mới và các lớp bảo vệ an toàn."},{"role":"B","speakerName":"Khách hàng / Product Owner","en":"Sounds great. How does the system prevent adults from pairing with students under 18?","vi":"Nghe hay đấy. Hệ thống ngăn người trưởng thành ghép cặp với học sinh dưới 18 tuổi bằng cách nào?"},{"role":"A","speakerName":"Lập trình viên Demo","en":"Our backend endpoint checks the user''s verified age group and filters matching pools server-side—not just in the UI.","vi":"Endpoint máy chủ kiểm tra nhóm tuổi đã xác nhận và lọc nhóm ghép cặp ngay ở phía server—chứ không chỉ ẩn trên giao diện."}]', '{"title":"Vai A · Lập trình viên trình bày Demo","goal":"Giải thích dễ hiểu cách hệ thống hoạt động mà không sa đà quá sâu vào code.","tasks":["Tóm tắt mục tiêu tính năng trong 30 giây.","Giải thích 1 cơ chế kiểm tra dữ liệu / bảo mật phía API.","Ghi nhận ít nhất 1 yêu cầu chỉnh sửa từ khách hàng."]}', '{"title":"Vai B · Product Owner / Khách hàng","goal":"Đặt câu hỏi kiểm tra tính thực tế, bảo mật và trải nghiệm người dùng.","tasks":["Hỏi về tốc độ tải hoặc xử lý trường hợp ngoại lệ.","Đề xuất 1 cải tiến nhỏ cho giao diện."]}', '[{"id":"terminology","criterion":"Thuật ngữ chuyên ngành","description":"Dùng đúng và tự nhiên các từ vựng, cụm từ kỹ thuật/nghề nghiệp của tình huống.","maxScore":5},{"id":"clarity","criterion":"Phát âm & Độ rõ ý","description":"Phát âm từ khóa quan trọng (thông số, lỗi, hành động) dễ hiểu với bạn cùng luyện.","maxScore":5},{"id":"task_completion","criterion":"Xử lý đúng trọng tâm","description":"Hoàn thành đầy đủ nhiệm vụ của vai đóng và phản hồi sát câu hỏi đối phương.","maxScore":5},{"id":"interaction","criterion":"Phản xạ & Xác nhận thông tin","description":"Biết hỏi lại khi chưa rõ, xác nhận thông số/thời hạn để tránh hiểu nhầm công việc.","maxScore":5},{"id":"professionalism","criterion":"Thái độ nghề nghiệp","description":"Giữ giọng điệu lịch sự, hợp tác và đúng quy tắc an toàn/văn hóa nơi làm việc.","maxScore":5}]', 'Bùi Tấn Lộc', 'GV chuyên môn Khoa Tin học · VSVC', 'Biên soạn từ quy trình nghiệm thu phần mềm Sprint Review.', 11, '2026-11-17T00:00:00.000Z');
INSERT OR REPLACE INTO career_scenarios (id, slug, title, major, target_audience, level, summary, duration_minutes, is_free, vocab_json, phrases_json, dialogue_json, role_a_json, role_b_json, rubric_json, author_name, reviewed_by_teacher, source_attribution, display_order, created_at) VALUES ('csc_12', 'phong-van-thuc-tap-sinh-junior-developer', 'Phỏng vấn Thực tập sinh / Junior Developer bằng tiếng Anh', 'Tin học', 'Học sinh, sinh viên Cao đẳng nghề • Trung cấp nghề • GDNN - GDTX', 'Trung bình (B1)', 'Giới thiệu dự án web cá nhân (Next.js / Database), giải thích một lỗi từng xử lý và cách phối hợp nhóm bằng Git.', 20, 1, '[{"word":"tech stack","phonetic":"/tek stæk/","pos":"noun","meaning":"tập hợp công nghệ sử dụng trong dự án","example":"Our tech stack includes Next.js, TypeScript, and Prisma."},{"word":"database schema","phonetic":"/ˈdeɪ.tə.beɪs ˈskiː.mə/","pos":"noun","meaning":"lược đồ cơ sở dữ liệu","example":"I designed the database schema for user progress tracking."}]', '[{"en":"In my college startup project, I built the authentication and database API using Next.js and SQLite.","vi":"Trong dự án khởi nghiệp ở trường, tôi đã xây dựng phần xác thực và API dữ liệu bằng Next.js và SQLite.","context":"Giới thiệu dự án thực tế khi chưa có nhiều kinh nghiệm đi làm."}]', '[{"role":"A","speakerName":"Interviewer","en":"Tell me about a technical challenge you solved in your recent web project.","vi":"Hãy kể về một thử thách kỹ thuật bạn đã giải quyết trong dự án web gần đây."},{"role":"B","speakerName":"Candidate","en":"In our peer-practice web platform, we needed to prevent concurrent users from claiming the same slot twice. I handled this by checking status inside a database update guard.","vi":"Ở nền tảng web luyện nói theo cặp, tụi em cần tránh hai người cùng nhận một lịch hẹn. Em đã xử lý bằng điều kiện kiểm tra trạng thái ngay khi cập nhật cơ sở dữ liệu."}]', '{"title":"Vai A · Technical Interviewer","goal":"Tìm hiểu năng lực lập trình thực tế và tinh thần học hỏi của sinh viên.","tasks":["Hỏi về tech stack của dự án gần nhất.","Hỏi cách ứng viên tìm và sửa lỗi khi gặp bug khó."]}', '{"title":"Vai B · Ứng viên Junior / Thực tập sinh","goal":"Trình bày rõ ràng vai trò bản thân trong dự án, công nghệ đã dùng và bài học rút ra.","tasks":["Nêu rõ phần việc bạn trực tiếp viết code.","Kể 1 bug thực tế và cách giải quyết theo mô hình Vấn đề -> Cách làm -> Kết quả."]}', '[{"id":"terminology","criterion":"Thuật ngữ chuyên ngành","description":"Dùng đúng và tự nhiên các từ vựng, cụm từ kỹ thuật/nghề nghiệp của tình huống.","maxScore":5},{"id":"clarity","criterion":"Phát âm & Độ rõ ý","description":"Phát âm từ khóa quan trọng (thông số, lỗi, hành động) dễ hiểu với bạn cùng luyện.","maxScore":5},{"id":"task_completion","criterion":"Xử lý đúng trọng tâm","description":"Hoàn thành đầy đủ nhiệm vụ của vai đóng và phản hồi sát câu hỏi đối phương.","maxScore":5},{"id":"interaction","criterion":"Phản xạ & Xác nhận thông tin","description":"Biết hỏi lại khi chưa rõ, xác nhận thông số/thời hạn để tránh hiểu nhầm công việc.","maxScore":5},{"id":"professionalism","criterion":"Thái độ nghề nghiệp","description":"Giữ giọng điệu lịch sự, hợp tác và đúng quy tắc an toàn/văn hóa nơi làm việc.","maxScore":5}]', 'Bùi Tấn Lộc', 'GV hướng dẫn Nguyễn Xuân Tùng · VSVC', 'Biên soạn dành cho sinh viên lớp Tin học ứng dụng VSVC.', 12, '2026-11-17T00:00:00.000Z');
INSERT OR REPLACE INTO career_scenarios (id, slug, title, major, target_audience, level, summary, duration_minutes, is_free, vocab_json, phrases_json, dialogue_json, role_a_json, role_b_json, rubric_json, author_name, reviewed_by_teacher, source_attribution, display_order, created_at) VALUES ('csc_13', 'tiep-don-va-xu-ly-phan-nan-khach-quoc-te', 'Tiếp nhận & xử lý phàn nàn của khách hàng nước ngoài', 'Kinh tế - Du lịch', 'Học sinh, sinh viên Cao đẳng nghề • Trung cấp nghề • GDNN - GDTX', 'Cơ bản (A2)', 'Lắng nghe, xin lỗi chân thành, xác nhận phương án đổi phòng/khắc phục dịch vụ và theo dõi sự hài lòng của khách.', 15, 1, '[{"word":"inconvenience","phonetic":"/ˌɪn.kənˈviːn.jəns/","pos":"noun","meaning":"sự bất tiện","example":"We sincerely apologize for the inconvenience caused."},{"word":"complimentary","phonetic":"/ˌkɑːm.pləˈmen.t̬ər.i/","pos":"adjective","meaning":"miễn phí (tặng kèm để tri ân/xin lỗi)","example":"We would like to offer a complimentary late check-out."}]', '[{"en":"I sincerely apologize for the noise issue. Let me arrange a quieter room for you right away.","vi":"Tôi thành thật xin lỗi vì sự cố tiếng ồn. Hãy để tôi sắp xếp ngay một phòng yên tĩnh hơn cho quý khách.","context":"Xin lỗi và đưa ra giải pháp tức thì."}]', '[{"role":"A","speakerName":"Khách quốc tế","en":"Excuse me, the air conditioner in my room is leaking and making a loud noise.","vi":"Xin lỗi, máy lạnh ở phòng tôi đang bị rỉ nước và kêu khá to."},{"role":"B","speakerName":"Nhân viên Lễ tân","en":"I am truly sorry for the inconvenience, sir. I can upgrade you to a quieter room on the fifth floor right away while our technician fixes that unit.","vi":"Em thành thật xin lỗi vì sự bất tiện này ạ. Em có thể chuyển anh lên phòng yên tĩnh hơn ở tầng 5 ngay bây giờ trong lúc kỹ thuật viên sửa máy ạ."}]', '{"title":"Vai A · Khách hàng nước ngoài","goal":"Trình bày rõ vấn đề dịch vụ đang gặp và kỳ vọng được xử lý nhanh.","tasks":["Mô tả vấn đề cụ thể gặp phải.","Hỏi về thời gian giải quyết hoặc phương án thay thế."]}', '{"title":"Vai B · Nhân viên Dịch vụ / CSKH","goal":"Giữ thái độ điềm tĩnh, thấu cảm và đưa giải pháp cụ thể ngay.","tasks":["Xin lỗi lịch sự và lặp lại vấn đề để xác nhận đã hiểu đúng.","Đề xuất giải pháp ngay và thời gian hoàn tất."]}', '[{"id":"terminology","criterion":"Thuật ngữ chuyên ngành","description":"Dùng đúng và tự nhiên các từ vựng, cụm từ kỹ thuật/nghề nghiệp của tình huống.","maxScore":5},{"id":"clarity","criterion":"Phát âm & Độ rõ ý","description":"Phát âm từ khóa quan trọng (thông số, lỗi, hành động) dễ hiểu với bạn cùng luyện.","maxScore":5},{"id":"task_completion","criterion":"Xử lý đúng trọng tâm","description":"Hoàn thành đầy đủ nhiệm vụ của vai đóng và phản hồi sát câu hỏi đối phương.","maxScore":5},{"id":"interaction","criterion":"Phản xạ & Xác nhận thông tin","description":"Biết hỏi lại khi chưa rõ, xác nhận thông số/thời hạn để tránh hiểu nhầm công việc.","maxScore":5},{"id":"professionalism","criterion":"Thái độ nghề nghiệp","description":"Giữ giọng điệu lịch sự, hợp tác và đúng quy tắc an toàn/văn hóa nơi làm việc.","maxScore":5}]', 'Võ Gia Như', 'GV chuyên môn Tổ Dịch vụ - Du lịch · VSVC', 'Biên soạn phục vụ khối ngành Dịch vụ - Du lịch và mở rộng N2/N3.', 13, '2026-11-17T00:00:00.000Z');
INSERT OR REPLACE INTO career_scenarios (id, slug, title, major, target_audience, level, summary, duration_minutes, is_free, vocab_json, phrases_json, dialogue_json, role_a_json, role_b_json, rubric_json, author_name, reviewed_by_teacher, source_attribution, display_order, created_at) VALUES ('csc_14', 'xac-nhan-bao-gia-va-tien-do-giao-hang-doi-tac', 'Trao đổi báo giá & xác nhận tiến độ giao hàng với đối tác', 'Kinh tế - Du lịch', 'Học sinh, sinh viên Cao đẳng nghề • Trung cấp nghề • GDNN - GDTX', 'Trung bình (B1)', 'Thực hành trao đổi đơn giá, điều kiện thanh toán, chiết khấu số lượng và cam kết ngày giao hàng với đối tác nước ngoài.', 15, 0, '[{"word":"quotation","phonetic":"/kwoʊˈteɪ.ʃən/","pos":"noun","meaning":"bảng báo giá","example":"We will send the updated quotation before 5 PM today."},{"word":"lead time","phonetic":"/ˈliːd taɪm/","pos":"noun","meaning":"thời gian từ khi đặt hàng đến khi giao hàng","example":"Our standard production lead time is ten business days."}]', '[{"en":"If your order exceeds 500 units, we can offer a 5% volume discount.","vi":"Nếu đơn hàng vượt 500 sản phẩm, chúng tôi có thể chiết khấu 5% theo số lượng.","context":"Thương lượng mức giá linh hoạt theo số lượng."}]', '[{"role":"A","speakerName":"Điều phối đơn hàng","en":"Thank you for reviewing our quotation. Would you like to confirm the delivery schedule for the first 300 units?","vi":"Cảm ơn anh đã xem bảng báo giá. Anh có muốn xác nhận lịch giao hàng cho 300 sản phẩm đầu tiên không ạ?"},{"role":"B","speakerName":"Đối tác mua hàng","en":"Yes, we need them by the 25th of this month. Can your team meet that lead time?","vi":"Có, bên tôi cần nhận hàng trước ngày 25 tháng này. Đội bạn có đáp ứng kịp thời gian giao hàng đó không?"}]', '{"title":"Vai A · Nhân viên Kinh doanh / Điều phối","goal":"Thuyết phục đối tác chốt đơn với thông tin rõ ràng về giá và thời hạn giao hàng.","tasks":["Xác nhận số lượng, đơn giá và điều khoản thanh toán.","Nêu rõ lead time và gửi email xác nhận lại bằng văn bản."]}', '{"title":"Vai B · Đối tác mua hàng","goal":"Đàm phán thời gian giao hàng và mức chiết khấu hợp lý.","tasks":["Yêu cầu thời hạn giao hàng cụ thể.","Đề nghị chiết khấu khi tăng số lượng đơn tiếp theo."]}', '[{"id":"terminology","criterion":"Thuật ngữ chuyên ngành","description":"Dùng đúng và tự nhiên các từ vựng, cụm từ kỹ thuật/nghề nghiệp của tình huống.","maxScore":5},{"id":"clarity","criterion":"Phát âm & Độ rõ ý","description":"Phát âm từ khóa quan trọng (thông số, lỗi, hành động) dễ hiểu với bạn cùng luyện.","maxScore":5},{"id":"task_completion","criterion":"Xử lý đúng trọng tâm","description":"Hoàn thành đầy đủ nhiệm vụ của vai đóng và phản hồi sát câu hỏi đối phương.","maxScore":5},{"id":"interaction","criterion":"Phản xạ & Xác nhận thông tin","description":"Biết hỏi lại khi chưa rõ, xác nhận thông số/thời hạn để tránh hiểu nhầm công việc.","maxScore":5},{"id":"professionalism","criterion":"Thái độ nghề nghiệp","description":"Giữ giọng điệu lịch sự, hợp tác và đúng quy tắc an toàn/văn hóa nơi làm việc.","maxScore":5}]', 'Vũ Tiến Anh', 'GV chuyên môn Tổ Kinh tế · VSVC', 'Biên soạn phục vụ nhóm N2 (Kinh tế) & N3 (Nhân viên văn phòng).', 14, '2026-11-17T00:00:00.000Z');
INSERT OR REPLACE INTO career_scenarios (id, slug, title, major, target_audience, level, summary, duration_minutes, is_free, vocab_json, phrases_json, dialogue_json, role_a_json, role_b_json, rubric_json, author_name, reviewed_by_teacher, source_attribution, display_order, created_at) VALUES ('csc_15', 'chan-doan-loi-obd2-va-bao-duong-dong-co-o-to', 'Chẩn đoán lỗi OBD-II & báo cáo bảo dưỡng động cơ ô tô cho cố vấn dịch vụ', 'Công nghệ Ô tô', 'Học sinh, sinh viên Cao đẳng nghề • Trung cấp nghề • GDNN - GDTX', 'Cơ bản (A2)', 'Kỹ thuật viên ô tô đọc mã lỗi P0301 từ máy chẩn đoán OBD-II, kiểm tra bugi đánh lửa, kim phun nhiên liệu và báo giá thay thế cho cố vấn dịch vụ/khách hàng nước ngoài.', 15, 1, '[{"word":"diagnostic scanner","phonetic":"/ˌdaɪ.əɡˈnɑː.stɪk ˈskæn.ər/","pos":"noun","meaning":"máy chẩn đoán lỗi ô tô (OBD-II)","example":"Connect the diagnostic scanner to read the fault code."},{"word":"cylinder misfire","phonetic":"/ˈsɪl.ɪn.dər ˌmɪsˈfaɪr/","pos":"noun","meaning":"bỏ máy / mất lửa xi-lanh","example":"Fault code P0301 indicates a cylinder 1 misfire."},{"word":"spark plug","phonetic":"/spɑːrk plʌɡ/","pos":"noun","meaning":"bugi đánh lửa","example":"We need to replace the worn spark plugs."},{"word":"fuel injector","phonetic":"/ˈfjuː.əl ɪnˈdʒek.tər/","pos":"noun","meaning":"kim phun nhiên liệu","example":"The fuel injector is clogged with carbon deposits."},{"word":"brake pad","phonetic":"/breɪk pæd/","pos":"noun","meaning":"má phanh (bố thắng)","example":"The front brake pads are worn down to two millimeters."}]', '[{"en":"The OBD-II scanner shows fault code P0301, which means Cylinder 1 misfire.","vi":"Máy chẩn đoán OBD-II báo mã lỗi P0301, nghĩa là xi-lanh số 1 bị bỏ máy.","context":"Báo cáo mã lỗi chẩn đoán động cơ."},{"en":"We recommend replacing all four spark plugs and cleaning the fuel injectors.","vi":"Chúng tôi khuyến nghị thay cả 4 bugi và vệ sinh kim phun nhiên liệu.","context":"Đề xuất hạng mục sửa chữa bảo dưỡng."}]', '[{"role":"A","speakerName":"Kỹ thuật viên Ô tô (Lộc)","en":"Hi Mr. Mark, I finished scanning your SUV. The diagnostic scanner shows fault code P0301—a cylinder 1 misfire.","vi":"Chào anh Mark, tôi đã quét lỗi chiếc SUV của anh. Máy chẩn đoán báo mã P0301—bỏ lửa ở xi-lanh số 1."},{"role":"B","speakerName":"Chủ xe / Cố vấn (Mark)","en":"That explains why the engine was shaking at idle. What needs to be repaired?","vi":"Thảo nào máy bị rung khi nổ garanti. Cần phải sửa những gì vậy bạn?"},{"role":"A","speakerName":"Kỹ thuật viên Ô tô (Lộc)","en":"The spark plug in cylinder 1 is worn out, and the fuel injector is dirty. We can replace the spark plugs and clean the injectors within one hour.","vi":"Bugi xi-lanh 1 đã mòn và kim phun bị bẩn. Chúng tôi có thể thay bộ bugi và súc rửa kim phun trong vòng 1 giờ."},{"role":"B","speakerName":"Chủ xe / Cố vấn (Mark)","en":"Sounds good. Please also check the front brake pads before I pick up the car at 4 PM.","vi":"Tốt quá. Nhớ kiểm tra thêm má phanh trước giúp tôi trước khi tôi lấy xe lúc 4 giờ chiều nhé."}]', '{"title":"Vai A · Kỹ thuật viên Chẩn đoán Ô tô","goal":"Đọc mã lỗi OBD-II, giải thích nguyên nhân rung giật động cơ và chốt thời gian bảo dưỡng.","tasks":["Nêu mã lỗi P0301 và hiện tượng cylinder misfire.","Giải thích tình trạng bugi và kim phun.","Cam kết thời gian hoàn thành và kiểm tra thêm phanh."]}', '{"title":"Vai B · Khách hàng nước ngoài / Cố vấn dịch vụ","goal":"Xác nhận nguyên nhân lỗi, chi phí/thời gian sửa chữa và yêu cầu kiểm tra an toàn phanh.","tasks":["Mô tả triệu chứng rung máy khi dừng đèn đỏ.","Hỏi phương án khắc phục và thời gian nhận xe."]}', '[{"id":"terminology","criterion":"Thuật ngữ chuyên ngành","description":"Dùng đúng và tự nhiên các từ vựng, cụm từ kỹ thuật/nghề nghiệp của tình huống.","maxScore":5},{"id":"clarity","criterion":"Phát âm & Độ rõ ý","description":"Phát âm từ khóa quan trọng (thông số, lỗi, hành động) dễ hiểu với bạn cùng luyện.","maxScore":5},{"id":"task_completion","criterion":"Xử lý đúng trọng tâm","description":"Hoàn thành đầy đủ nhiệm vụ của vai đóng và phản hồi sát câu hỏi đối phương.","maxScore":5},{"id":"interaction","criterion":"Phản xạ & Xác nhận thông tin","description":"Biết hỏi lại khi chưa rõ, xác nhận thông số/thời hạn để tránh hiểu nhầm công việc.","maxScore":5},{"id":"professionalism","criterion":"Thái độ nghề nghiệp","description":"Giữ giọng điệu lịch sự, hợp tác và đúng quy tắc an toàn/văn hóa nơi làm việc.","maxScore":5}]', 'Bùi Tấn Lộc', 'GV chuyên môn Khoa Công nghệ Ô tô · Hệ Cao đẳng / Trung cấp nghề', 'Biên soạn từ giáo trình Thực hành Chẩn đoán Điện - Động cơ Ô tô hệ Cao đẳng nghề & GDNN-GDTX.', 15, '2026-11-17T00:00:00.000Z');
INSERT OR REPLACE INTO career_scenarios (id, slug, title, major, target_audience, level, summary, duration_minutes, is_free, vocab_json, phrases_json, dialogue_json, role_a_json, role_b_json, rubric_json, author_name, reviewed_by_teacher, source_attribution, display_order, created_at) VALUES ('csc_16', 'kiem-tra-he-thong-pin-cao-ap-xe-dien-ev', 'Quy trình an toàn & kiểm tra hệ thống pin cao áp xe điện (EV / Hybrid)', 'Công nghệ Ô tô', 'Học sinh, sinh viên Cao đẳng nghề • Trung cấp nghề • GDNN - GDTX', 'Trung bình (B1)', 'Thực hành giao tiếp kỹ thuật khi ngắt cầu dao an toàn (service plug), kiểm tra cách điện và cân bằng cell pin trên dòng xe điện thế hệ mới.', 15, 1, '[{"word":"high-voltage battery","phonetic":"/ˌhaɪˈvoʊl.tɪdʒ ˈbæt.ər.i/","pos":"noun","meaning":"khối pin cao áp","example":"Always wear Class 0 gloves when working near the high-voltage battery."},{"word":"service disconnect plug","phonetic":"/ˈsɜːr.vɪs ˌdɪs.kəˈnekt plʌɡ/","pos":"noun","meaning":"chốt/cầu dao ngắt điện an toàn bảo dưỡng","example":"Remove the service disconnect plug and wait ten minutes for capacitors to discharge."},{"word":"insulation resistance","phonetic":"/ˌɪn.sjəˈleɪ.ʃən rɪˈzɪs.təns/","pos":"noun","meaning":"điện trở cách điện","example":"The insulation resistance test passed at 500 volts."}]', '[{"en":"Have you pulled the service disconnect plug and waited for ten minutes?","vi":"Bạn đã rút chốt ngắt an toàn và đợi đủ 10 phút xả tụ chưa?","context":"Kiểm tra an toàn điện cao áp trên xe EV."}]', '[{"role":"A","speakerName":"Trưởng nhóm Kỹ thuật EV","en":"Before we inspect the inverter cable, have you removed the service disconnect plug?","vi":"Trước khi kiểm tra cáp biến tần, bạn đã rút chốt ngắt an toàn chưa?"},{"role":"B","speakerName":"Kỹ thuật viên EV","en":"Yes, I pulled the service plug, waited ten minutes, and verified zero volts at the high-voltage terminals.","vi":"Dạ rồi, em đã rút chốt an toàn, chờ 10 phút và đo xác nhận 0 vôn tại các cực cao áp."}]', '{"title":"Vai A · Trưởng nhóm Kỹ thuật Xe điện","goal":"Giám sát nghiêm ngặt quy trình ngắt nguồn cao áp trước khi tháo cụm biến tần.","tasks":["Hỏi xác nhận đã tháo service plug và xả điện tụ chưa.","Yêu cầu báo cáo thông số điện trở cách điện."]}', '{"title":"Vai B · Kỹ thuật viên Bảo dưỡng EV","goal":"Báo cáo đầy đủ các bước bảo hộ và kết quả đo kiểm 0V.","tasks":["Nêu rõ các bước tháo chốt, chờ xả tụ và đo kiểm bằng đồng hồ.","Báo cáo tình trạng giắc cắm cao áp."]}', '[{"id":"terminology","criterion":"Thuật ngữ chuyên ngành","description":"Dùng đúng và tự nhiên các từ vựng, cụm từ kỹ thuật/nghề nghiệp của tình huống.","maxScore":5},{"id":"clarity","criterion":"Phát âm & Độ rõ ý","description":"Phát âm từ khóa quan trọng (thông số, lỗi, hành động) dễ hiểu với bạn cùng luyện.","maxScore":5},{"id":"task_completion","criterion":"Xử lý đúng trọng tâm","description":"Hoàn thành đầy đủ nhiệm vụ của vai đóng và phản hồi sát câu hỏi đối phương.","maxScore":5},{"id":"interaction","criterion":"Phản xạ & Xác nhận thông tin","description":"Biết hỏi lại khi chưa rõ, xác nhận thông số/thời hạn để tránh hiểu nhầm công việc.","maxScore":5},{"id":"professionalism","criterion":"Thái độ nghề nghiệp","description":"Giữ giọng điệu lịch sự, hợp tác và đúng quy tắc an toàn/văn hóa nơi làm việc.","maxScore":5}]', 'Cao Anh Nhựt', 'GV chuyên môn Khoa Công nghệ Ô tô · VSVC', 'Biên soạn theo mô-đun Bảo dưỡng Xe điện & Hybrid hệ Cao đẳng nghề.', 16, '2026-11-17T00:00:00.000Z');
INSERT OR REPLACE INTO career_scenarios (id, slug, title, major, target_audience, level, summary, duration_minutes, is_free, vocab_json, phrases_json, dialogue_json, role_a_json, role_b_json, rubric_json, author_name, reviewed_by_teacher, source_attribution, display_order, created_at) VALUES ('csc_17', 'tiep-nhan-design-brief-va-chot-file-in-an', 'Tiếp nhận yêu cầu thiết kế (Design Brief) & kiểm tra thông số file in ấn', 'Thiết kế Đồ họa', 'Học sinh, sinh viên Cao đẳng nghề • Trung cấp nghề • GDNN - GDTX', 'Cơ bản (A2)', 'Sinh viên ngành Thiết kế Đồ họa trao đổi với khách hàng về bảng màu thương hiệu, bố cục poster, hệ màu CMYK, tràn lề (bleed 3mm) và xuất file in chuẩn.', 15, 1, '[{"word":"design brief","phonetic":"/dɪˈzaɪn briːf/","pos":"noun","meaning":"bản mô tả yêu cầu thiết kế","example":"Please review the design brief before sketching the logo."},{"word":"bleed area","phonetic":"/bliːd ˈer.i.ə/","pos":"noun","meaning":"vùng tràn lề khi in (thường 3mm)","example":"Make sure the background extends to the 3mm bleed area."},{"word":"color mode","phonetic":"/ˈkʌl.ər moʊd/","pos":"noun","meaning":"hệ màu (CMYK cho in ấn, RGB cho màn hình)","example":"Convert the document color mode from RGB to CMYK before exporting."},{"word":"vector outline","phonetic":"/ˈvek.tər ˈaʊt.laɪn/","pos":"noun","meaning":"đường nét vector / đã convert font chữ (curves)","example":"Convert all text to vector outlines to avoid missing fonts at the print shop."}]', '[{"en":"I have converted all fonts to curves and set a 3-millimeter bleed for offset printing.","vi":"Tôi đã chuyển toàn bộ font chữ thành đường cong (curves) và đặt tràn lề 3mm cho in offset.","context":"Bàn giao file thiết kế đi in."},{"en":"Would you prefer a minimalist layout or a bold, vibrant style for the event backdrop?","vi":"Anh/chị thích bố cục tối giản hay phong cách nổi bật, rực rỡ cho phông nền sự kiện?","context":"Làm rõ định hướng mỹ thuật với khách hàng."}]', '[{"role":"A","speakerName":"Designer (Lộc)","en":"Hi Sarah, here is the first draft of the exhibition standee based on your design brief.","vi":"Chào Sarah, đây là bản phác thảo đầu tiên của standee triển lãm dựa trên bản yêu cầu thiết kế của chị."},{"role":"B","speakerName":"Khách hàng (Sarah)","en":"The visual hierarchy looks clean! Can we make the headline slightly larger and prepare the file for printing today?","vi":"Phân cấp thị giác nhìn rất gọn! Mình tăng kích thước tiêu đề lên một chút và xuất file in ngay hôm nay được không?"},{"role":"A","speakerName":"Designer (Lộc)","en":"Absolutely. I will enlarge the title, switch the color mode to CMYK, convert all text to vector outlines, and add a 3mm bleed.","vi":"Chắc chắn rồi ạ. Em sẽ phóng to tiêu đề, chuyển hệ màu sang CMYK, convert toàn bộ chữ sang vector curves và thêm tràn lề 3mm."},{"role":"B","speakerName":"Khách hàng (Sarah)","en":"Perfect. Please upload both the print-ready PDF and the preview PNG to our shared folder.","vi":"Tuyệt vời. Nhớ tải cả file PDF chuẩn in và ảnh PNG xem trước lên thư mục chung giúp chị nhé."}]', '{"title":"Vai A · Chuyên viên Thiết kế Đồ họa (Graphic Designer)","goal":"Trình bày phương án thiết kế, tiếp nhận chỉnh sửa bố cục và cam kết chuẩn kỹ thuật file in.","tasks":["Giới thiệu bố cục bản thiết kế theo design brief.","Tiếp nhận yêu cầu chỉnh sửa kích thước/màu sắc.","Xác nhận thông số kỹ thuật in: CMYK, 300 DPI, 3mm bleed, convert font."]}', '{"title":"Vai B · Khách hàng / Art Director","goal":"Đánh giá tính thẩm mỹ, góp ý chỉnh sửa chi tiết và kiểm tra quy cách xuất file in.","tasks":["Nhận xét ưu điểm của bản thiết kế.","Yêu cầu 1 chỉnh sửa nhỏ về cỡ chữ hoặc độ tương phản.","Yêu cầu bàn giao file PDF chuẩn in."]}', '[{"id":"terminology","criterion":"Thuật ngữ chuyên ngành","description":"Dùng đúng và tự nhiên các từ vựng, cụm từ kỹ thuật/nghề nghiệp của tình huống.","maxScore":5},{"id":"clarity","criterion":"Phát âm & Độ rõ ý","description":"Phát âm từ khóa quan trọng (thông số, lỗi, hành động) dễ hiểu với bạn cùng luyện.","maxScore":5},{"id":"task_completion","criterion":"Xử lý đúng trọng tâm","description":"Hoàn thành đầy đủ nhiệm vụ của vai đóng và phản hồi sát câu hỏi đối phương.","maxScore":5},{"id":"interaction","criterion":"Phản xạ & Xác nhận thông tin","description":"Biết hỏi lại khi chưa rõ, xác nhận thông số/thời hạn để tránh hiểu nhầm công việc.","maxScore":5},{"id":"professionalism","criterion":"Thái độ nghề nghiệp","description":"Giữ giọng điệu lịch sự, hợp tác và đúng quy tắc an toàn/văn hóa nơi làm việc.","maxScore":5}]', 'Bùi Tấn Lộc', 'GV chuyên môn Khoa Thiết kế Đồ họa · Trường CĐ nghề Việt Nam - Singapore', 'Biên soạn từ đồ án Thiết kế Đồ họa ứng dụng (CorelDRAW / Illustrator) tại VSVC.', 17, '2026-11-17T00:00:00.000Z');
INSERT OR REPLACE INTO career_scenarios (id, slug, title, major, target_audience, level, summary, duration_minutes, is_free, vocab_json, phrases_json, dialogue_json, role_a_json, role_b_json, rubric_json, author_name, reviewed_by_teacher, source_attribution, display_order, created_at) VALUES ('csc_18', 'thuyet-trinh-bo-nhan-dien-thuong-hieu-va-ui-ux', 'Bảo vệ ý tưởng Bộ nhận diện thương hiệu (Brand Guidelines) & giao diện UI/UX', 'Thiết kế Đồ họa', 'Học sinh, sinh viên Cao đẳng nghề • Trung cấp nghề • GDNN - GDTX', 'Trung bình (B1)', 'Thuyết trình ý nghĩa biểu trưng (logo), tỷ lệ lưới quy chuẩn, bộ chữ (typography) và khả năng hiển thị đáp ứng trên thiết bị di động.', 15, 1, '[{"word":"brand identity","phonetic":"/brænd aɪˈden.tə.t̬i/","pos":"noun","meaning":"bộ nhận diện thương hiệu","example":"A consistent brand identity builds trust across all platforms."},{"word":"contrast ratio","phonetic":"/ˈkɑːn.træst ˈreɪ.ʃi.oʊ/","pos":"noun","meaning":"tỷ lệ tương phản màu sắc","example":"Our text meets the WCAG contrast ratio for readability."}]', '[{"en":"We chose deep teal and vermilion red to convey both reliability and youthful energy.","vi":"Chúng tôi chọn tông xanh cổ vịt đậm và đỏ son để truyền tải cả sự tin cậy lẫn năng lượng trẻ trung.","context":"Giải thích ý nghĩa bảng màu thương hiệu."}]', '[{"role":"A","speakerName":"Brand Designer","en":"In this brand guideline, we paired a geometric sans-serif heading font with high contrast ratios for mobile screens.","vi":"Trong bộ quy chuẩn thương hiệu này, tụi em kết hợp font tiêu đề không chân hình học với độ tương phản cao cho màn hình di động."},{"role":"B","speakerName":"Giám đốc Sáng tạo","en":"How does the logo scale when displayed as a small 32-pixel mobile app icon?","vi":"Logo sẽ hiển thị thế nào khi thu nhỏ thành biểu tượng ứng dụng 32 pixel trên điện thoại?"},{"role":"A","speakerName":"Brand Designer","en":"We created a simplified emblem version without the slogan so it remains sharp even at 16 or 32 pixels.","vi":"Tụi em đã thiết kế phiên bản biểu tượng rút gọn lược bỏ dòng slogan để giữ độ sắc nét ngay cả ở kích thước 16 hoặc 32 pixel."}]', '{"title":"Vai A · Nhà thiết kế Thương hiệu / UI","goal":"Giải thích lý do chọn màu sắc, font chữ và phương án hiển thị logo kích thước nhỏ.","tasks":["Trình bày ý nghĩa màu chủ đạo và font chữ.","Giải thích phương án responsive icon trên di động."]}', '{"title":"Vai B · Giám đốc Sáng tạo / Hội đồng chấm đồ án","goal":"Phản biện tính ứng dụng thực tế của bộ nhận diện trên đa nền tảng.","tasks":["Hỏi về khả năng hiển thị của logo trên nền tối và kích thước nhỏ.","Đánh giá tính đồng bộ."]}', '[{"id":"terminology","criterion":"Thuật ngữ chuyên ngành","description":"Dùng đúng và tự nhiên các từ vựng, cụm từ kỹ thuật/nghề nghiệp của tình huống.","maxScore":5},{"id":"clarity","criterion":"Phát âm & Độ rõ ý","description":"Phát âm từ khóa quan trọng (thông số, lỗi, hành động) dễ hiểu với bạn cùng luyện.","maxScore":5},{"id":"task_completion","criterion":"Xử lý đúng trọng tâm","description":"Hoàn thành đầy đủ nhiệm vụ của vai đóng và phản hồi sát câu hỏi đối phương.","maxScore":5},{"id":"interaction","criterion":"Phản xạ & Xác nhận thông tin","description":"Biết hỏi lại khi chưa rõ, xác nhận thông số/thời hạn để tránh hiểu nhầm công việc.","maxScore":5},{"id":"professionalism","criterion":"Thái độ nghề nghiệp","description":"Giữ giọng điệu lịch sự, hợp tác và đúng quy tắc an toàn/văn hóa nơi làm việc.","maxScore":5}]', 'Bùi Tấn Lộc', 'GV chuyên môn Khoa Thiết kế Đồ họa · VSVC', 'Biên soạn cho sinh viên ngành Thiết kế Đồ họa & Truyền thông đa phương tiện.', 18, '2026-11-17T00:00:00.000Z');
INSERT OR REPLACE INTO career_scenarios (id, slug, title, major, target_audience, level, summary, duration_minutes, is_free, vocab_json, phrases_json, dialogue_json, role_a_json, role_b_json, rubric_json, author_name, reviewed_by_teacher, source_attribution, display_order, created_at) VALUES ('csc_19', 'hoi-benh-su-va-do-sinh-hieu-benh-nhan-nuoc-ngoai', 'Tiếp đón, hỏi triệu chứng & đo dấu hiệu sinh tồn cho bệnh nhân nước ngoài', 'Điều dưỡng - Y dược', 'Học sinh, sinh viên Cao đẳng nghề • Trung cấp nghề • GDNN - GDTX', 'Cơ bản (A2)', 'Tình huống thực hành dành cho học sinh, sinh viên Cao đẳng/Trung cấp Điều dưỡng – Y dược: hỏi vị trí đau, tiền sử dị ứng thuốc và hướng dẫn đo huyết áp, thân nhiệt.', 15, 1, '[{"word":"vital signs","phonetic":"/ˈvaɪ.t̬əl saɪnz/","pos":"noun","meaning":"dấu hiệu sinh tồn (mạch, nhiệt, huyết áp, nhịp thở)","example":"Let me check your vital signs before the doctor sees you."},{"word":"blood pressure","phonetic":"/ˈblʌd ˌpreʃ.ər/","pos":"noun","meaning":"huyết áp","example":"Your blood pressure is 120 over 80, which is normal."},{"word":"allergic to","phonetic":"/əˈlɜːr.dʒɪk tuː/","pos":"adjective phrase","meaning":"bị dị ứng với (thuốc / thức ăn)","example":"Are you allergic to any medication, such as penicillin?"}]', '[{"en":"Please roll up your sleeve so I can take your blood pressure.","vi":"Vui lòng xắn tay áo lên để tôi đo huyết áp cho anh/chị nhé.","context":"Giao tiếp điều dưỡng khi đo sinh hiệu."},{"en":"On a scale from 1 to 10, how severe is the pain?","vi":"Trên thang điểm từ 1 đến 10, mức độ đau của anh/chị là bao nhiêu?","context":"Đánh giá mức độ đau của bệnh nhân."}]', '[{"role":"A","speakerName":"Điều dưỡng viên (Như)","en":"Good morning. Please take a seat and roll up your left sleeve so I can check your vital signs.","vi":"Chào anh. Mời anh ngồi và xắn tay áo bên trái lên để tôi kiểm tra dấu hiệu sinh tồn nhé."},{"role":"B","speakerName":"Bệnh nhân nước ngoài","en":"Thank you, nurse. I have had a mild fever and a sore throat since yesterday evening.","vi":"Cảm ơn cô y tá. Tôi bị sốt nhẹ và đau họng từ tối hôm qua."},{"role":"A","speakerName":"Điều dưỡng viên (Như)","en":"Your temperature is 38.2 degrees Celsius and your blood pressure is 120 over 80. Are you allergic to any medication?","vi":"Nhiệt độ của anh là 38,2 độ C và huyết áp là 120/80. Anh có bị dị ứng với loại thuốc nào không?"},{"role":"B","speakerName":"Bệnh nhân nước ngoài","en":"No, I have no known drug allergies.","vi":"Không, tôi không bị dị ứng thuốc nào cả."}]', '{"title":"Vai A · Điều dưỡng viên / Y sĩ","goal":"Hướng dẫn bệnh nhân đo sinh hiệu nhẹ nhàng, hỏi triệu chứng và tiền sử dị ứng thuốc.","tasks":["Mời bệnh nhân ngồi và đo huyết áp, nhiệt độ.","Thông báo chỉ số rõ ràng.","Hỏi tiền sử dị ứng thuốc trước khi chuyển bác sĩ."]}', '{"title":"Vai B · Bệnh nhân người nước ngoài","goal":"Mô tả triệu chứng sốt/đau họng, thời gian khởi phát và trả lời câu hỏi dị ứng.","tasks":["Nêu 2 triệu chứng chính và thời điểm bắt đầu.","Xác nhận thông tin dị ứng thuốc."]}', '[{"id":"terminology","criterion":"Thuật ngữ chuyên ngành","description":"Dùng đúng và tự nhiên các từ vựng, cụm từ kỹ thuật/nghề nghiệp của tình huống.","maxScore":5},{"id":"clarity","criterion":"Phát âm & Độ rõ ý","description":"Phát âm từ khóa quan trọng (thông số, lỗi, hành động) dễ hiểu với bạn cùng luyện.","maxScore":5},{"id":"task_completion","criterion":"Xử lý đúng trọng tâm","description":"Hoàn thành đầy đủ nhiệm vụ của vai đóng và phản hồi sát câu hỏi đối phương.","maxScore":5},{"id":"interaction","criterion":"Phản xạ & Xác nhận thông tin","description":"Biết hỏi lại khi chưa rõ, xác nhận thông số/thời hạn để tránh hiểu nhầm công việc.","maxScore":5},{"id":"professionalism","criterion":"Thái độ nghề nghiệp","description":"Giữ giọng điệu lịch sự, hợp tác và đúng quy tắc an toàn/văn hóa nơi làm việc.","maxScore":5}]', 'Võ Gia Như', 'GV chuyên môn Khối Sức khỏe - Điều dưỡng', 'Biên soạn theo chương trình Tiếng Anh chuyên ngành Điều dưỡng - Y sĩ đa khoa.', 19, '2026-11-17T00:00:00.000Z');
INSERT OR REPLACE INTO career_scenarios (id, slug, title, major, target_audience, level, summary, duration_minutes, is_free, vocab_json, phrases_json, dialogue_json, role_a_json, role_b_json, rubric_json, author_name, reviewed_by_teacher, source_attribution, display_order, created_at) VALUES ('csc_20', 'kiem-tra-chung-tu-hai-quan-va-lich-tau-logistics', 'Đối chiếu chứng từ vận đơn (Bill of Lading) & điều phối giao nhận kho vận', 'Logistics - Xuất nhập khẩu', 'Học sinh, sinh viên Cao đẳng nghề • Trung cấp nghề • GDNN - GDTX', 'Trung bình (B1)', 'Nhân viên chứng từ / kho vận đối chiếu số container, số chì (seal), mã HS code trên vận đơn và hẹn giờ xe đầu kéo vào cảng lấy hàng.', 15, 1, '[{"word":"bill of lading","phonetic":"/ˌbɪl əv ˈleɪ.dɪŋ/","pos":"noun","meaning":"vận đơn đường biển (B/L)","example":"Please verify the consignee address on the bill of lading."},{"word":"customs clearance","phonetic":"/ˈkʌs.təmz ˈklɪr.əns/","pos":"noun","meaning":"thông quan hải quan","example":"Customs clearance was completed this morning."},{"word":"packing list","phonetic":"/ˈpæk.ɪŋ lɪst/","pos":"noun","meaning":"phiếu đóng gói hàng hóa","example":"The net weight on the packing list must match the invoice."}]', '[{"en":"We noticed a discrepancy in the gross weight between the commercial invoice and the packing list.","vi":"Chúng tôi phát hiện sự chênh lệch trọng lượng cả bì giữa hóa đơn thương mại và phiếu đóng gói.","context":"Báo lỗi sai lệch chứng từ xuất nhập khẩu."}]', '[{"role":"A","speakerName":"Nhân viên Chứng từ (Tiến Anh)","en":"Hi Jenny, we are preparing customs clearance for shipment VN-208, but the gross weight on the packing list differs from the bill of lading.","vi":"Chào Jenny, bên mình đang chuẩn bị thông quan cho lô hàng VN-208, nhưng trọng lượng cả bì trên packing list đang lệch so với vận đơn."},{"role":"B","speakerName":"Đại lý Giao nhận (Jenny)","en":"Let me check right away. The correct gross weight is 12,400 kilograms. I will send the revised packing list within 15 minutes.","vi":"Để mình kiểm tra ngay. Trọng lượng đúng là 12.400 kg. Mình sẽ gửi lại bản packing list đã chỉnh sửa trong 15 phút nữa nhé."}]', '{"title":"Vai A · Nhân viên Hiện trường / Chứng từ Logistics","goal":"Phát hiện điểm lệch trên bộ chứng từ và yêu cầu đối tác cập nhật kịp giờ thông quan.","tasks":["Nêu mã lô hàng và chỉ rõ thông số bị lệch.","Xác nhận thời hạn nhận lại chứng từ đúng để kịp lịch kéo container."]}', '{"title":"Vai B · Đại lý Hàng hải / Forwarder quốc tế","goal":"Kiểm tra lại số liệu kho và gửi chứng từ điều chỉnh nhanh chóng.","tasks":["Xác nhận lại trọng lượng/số kiện chuẩn xác.","Cam kết thời gian gửi bản sửa đổi."]}', '[{"id":"terminology","criterion":"Thuật ngữ chuyên ngành","description":"Dùng đúng và tự nhiên các từ vựng, cụm từ kỹ thuật/nghề nghiệp của tình huống.","maxScore":5},{"id":"clarity","criterion":"Phát âm & Độ rõ ý","description":"Phát âm từ khóa quan trọng (thông số, lỗi, hành động) dễ hiểu với bạn cùng luyện.","maxScore":5},{"id":"task_completion","criterion":"Xử lý đúng trọng tâm","description":"Hoàn thành đầy đủ nhiệm vụ của vai đóng và phản hồi sát câu hỏi đối phương.","maxScore":5},{"id":"interaction","criterion":"Phản xạ & Xác nhận thông tin","description":"Biết hỏi lại khi chưa rõ, xác nhận thông số/thời hạn để tránh hiểu nhầm công việc.","maxScore":5},{"id":"professionalism","criterion":"Thái độ nghề nghiệp","description":"Giữ giọng điệu lịch sự, hợp tác và đúng quy tắc an toàn/văn hóa nơi làm việc.","maxScore":5}]', 'Vũ Tiến Anh', 'GV chuyên môn Khoa Kinh tế - Logistics', 'Biên soạn phục vụ học sinh, sinh viên nghề Logistics, Kế toán doanh nghiệp & Thương mại.', 20, '2026-11-17T00:00:00.000Z');
